(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-vae-tile-decode"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-1\">一 · 事故现场：一张 2048² 图把解码卡打死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-2\">二 · 它解决什么：显存受限下的解码可行性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-3\">三 · 它不解决什么：三类边界必须提前讲明</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-4\">四 · 代价结构：用重叠计算换显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-5\">五 · 失败模式：色带、断裂与反向收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-6\">六 · 显存墙下的解码失败：分块并行能救什么、救不了什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-7\">七 · 切分：从 latent 网格到带重叠的 tile 集合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-8\">八 · 逐 tile 解码：把激活峰值锁死在单 tile 内</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-9\">九 · 重叠区融合：按距离加权的线性叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-10\">十 · 写回与释放：输出缓冲的生命周期</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-11\">十一 · 全局一致性校正：一次收尾的分布对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-12\">十二 · 步骤间的代价传导与配方选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-13\">十三 · 峰值显存公式：从全图激活到单 tile 上界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-14\">十四 · 加权融合公式：距离权重与归一化分母</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-15\">十五 · 感受野截断：为什么边界细节会不一致</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-16\">十六 · 伪代码：可落地的 tile 循环与融合写回</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-17\">十七 · 收尾校正与失败模式的量化视角</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-18\">十八 · 重叠融合的失效边界与 tile 尺寸的代价曲线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-19\">十九 · 请求形态的匹配面：什么负载落在配方里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-20\">二十 · 批内 tile 混排的调度机制与填谷代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-21\">二十一 · 长度分布偏移下的 tile 数与重叠占比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-22\">二十二 · 负载不对时的三种失效形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-23\">二十三 · 配方参数与硬件档位的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-24\">二十四 · 负载配方的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-25\">二十五 · 硬件档位：以单 tile 峰值为选卡依据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-26\">二十六 · 并行拓扑：tile 级多 stream 与融合的同步点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-27\">二十七 · 量化方案：FP16 解码为主，融合保持高精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-28\">二十八 · KV 策略：无缓存的显存预算重分配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-29\">二十九 · 调度参数：tile 尺寸、重叠宽度与 $\\sigma$ 的联合标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-30\">三十 · 部署配方的失效边界与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-31\">三十一 · 部署配方的失效边界：从显存账本到接缝预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-32\">三十二 · 峰值显存的真实构成与“先崩点”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-33\">三十三 · 带宽：融合写回比解码本身更贵</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-34\">三十四 · 通信：tile 级并行的拓扑选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-35\">三十五 · 功耗与热：并发度是隐形的功耗旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-36\">三十六 · 尾延迟：融合同步点是长尾的来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-37\">三十七 · 规模上去以后，崩的顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-38\">三十八 · 规模上去以后：先崩在显存墙，再崩在重叠比与尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-39\">三十九 · 精度失败的三条链路：融合权重、感受野截断、全局校正失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-40\">四十 · 显存失败：峰值不在单 tile，而在缓冲与融合中间态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-41\">四十一 · 批抖动与路由不均：tile 粒度打散了批的语义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-42\">四十二 · 尾延迟尖刺：重叠带放大与融合串行点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-43\">四十三 · 监控面与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-44\">四十四 · 融合权重失配、感受野截断与 tile 粒度反噬：三类失效的定位与回滚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-45\">四十五 · 对照轴：切分发生在计算图的哪个位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-46\">四十六 · 决策表：四类候选与硬性适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-47\">四十七 · 融合公式的选型含义：权重带宽决定 tile 尺寸下限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-48\">四十八 · 时延模型：tile 并行度与 SLO 的匹配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-49\">四十九 · 质量风险的分工：谁负责接缝，谁负责一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-50\">五十 · 组合与禁用：与量化、缓存的相邻关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tile-decode-sec-51\">五十一 · 选型边界：什么条件下分块解码才成立</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">latent 按固定 tile 大小切分，边界留重叠像素</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">逐 tile 送 VAE 解码器，激活峰值限制在单 tile 内</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">重叠区按距离权重做线性融合，消除接缝</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码结果写回输出缓冲，释放 tile 激活</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">全部 tile 完成后做一次色彩/亮度一致性校正</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-vae-tile-decode-sec-1\">一 · 事故现场：一张 2048² 图把解码卡打死</h3>\n<p>某条高分辨率文生图服务上线后，去噪阶段一切正常，端到端吞吐却卡在一个谁也没预料到的位置：VAE 解码。请求形态是单张 2048² 图像，latent 送进解码器后，激活显存一路抬升，单张图的解码过程可占数十 GB，直接把一张卡的剩余显存吃干净。后果不是“慢一点”，而是连锁的：解码 kernel 触发显存不足回退，批内其他请求被拖住，连续批处理队列里排队的请求开始超时，SLO 从解码时延这一个点扩散成整条服务的尾延迟恶化。工程上最难受的是，去噪那侧的优化全都白做了——算力省下来的部分，被解码期的显存瓶颈原样吞掉。</p>\n<p>这个事故的性质需要说清楚：它不是算力不够，而是<strong>峰值显存</strong>不够。VAE 解码器的激活量随空间分辨率超线性增长，整图一次性解码意味着中间特征图必须同时驻留，峰值显存由全图尺寸决定而非由模型权重决定。于是出现一个反直觉的局面：模型参数明明装得下，卡却跑不动一张图。分块并行解码要解决的就是这个具体问题——把“峰值显存由全图决定”改成“峰值显存由单 tile 决定”。</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{peak}}\\approx \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}$$</div>\n<p>这个式子是整个算法的立足点。它说明峰值显存被拆成两块：模型权重是固定成本，tile 激活是可控成本。整图解码时第一项退化为全图激活，第二项不变；分块之后第一项被压到单 tile 量级，2048² 解码因此可以在单卡完成。注意这里没有把输出缓冲算进去——输出缓冲按全图尺寸分配，但它是逐 tile 写回的低带宽占用，与激活峰值不是同一量级的压力。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-2\">二 · 它解决什么：显存受限下的解码可行性</h3>\n<p>按数据流顺序，机制是这样的：latent 按固定 tile 大小切分，边界留重叠像素；每个 tile 单独送进 VAE 解码器，激活峰值被限制在单 tile 内；解码结果按重叠区做加权融合，消除接缝；结果写回输出缓冲后立即释放该 tile 的激活；全部 tile 完成后做一次色彩/亮度一致性校正。配合 FP16 解码与 kernel 融合，峰值显存进一步下压。</p>\n<p>它真正解决的问题有三个层次。第一层是可行性：让 2048² 这种分辨率在单卡上能解码，而不是必须换更大显存的卡或拆到多卡。第二层是吞吐：显存瓶颈解除后，批大小可以按单 tile 显存上限来设定，而不是被全图激活逼到 1。第三层是时延结构：tile 间彼此独立，可并行，多 stream 下解码时延随 tile 数近线性下降——这意味着解码不再是端到端流水里那块无法压缩的固定开销，而是一个可以按 tile 数摊薄的阶段。</p>\n<p>融合公式决定了接缝质量的上界：</p>\n<div class=\"formula\">$$\\hat{x}(u)=\\frac{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)\\,D_i(u)}{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)},\\quad w_i(u)=\\exp\\left(-\\frac{\\|u-c_i\\|_2^2}{2\\sigma^2}\\right)$$</div>\n<p>其中 $\\hat{x}(u)$ 是像素 $u$ 的融合输出，$D_i(u)$ 是第 $i$ 个 tile 的解码结果，$\\mathcal{N}(u)$ 是覆盖该像素的 tile 集合，$c_i$ 是 tile 中心，$\\sigma$ 是重叠区权重带宽。权重随到 tile 中心的距离指数衰减，意味着越靠近边界的 tile 贡献越小、越靠近中心的贡献越大，接缝处两侧 tile 的权重连续过渡。这个设计把“硬拼接”的阶跃变成了平滑过渡，代价是重叠区被计算了多次。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-3\">三 · 它不解决什么：三类边界必须提前讲明</h3>\n<p>第一，它不改去噪计算图。这是与阶段级流水、patch 级调度的根本差别：那些方法在去噪前或按管线阶段切分，影响的是整个扩散过程；本方法只在 VAE 解码期做空间切块，去噪那侧的显存与算力问题它一概不管。如果瓶颈在去噪侧的注意力激活，分块解码帮不上忙。</p>\n<p>第二，它不消除感受野截断。tile 边界处的解码器感受野被硬性切断，边界像素看到的上下文少于整图解码时的上下文，高频细节可能不一致——文字、细纹理处出现断裂是这类方法的固有风险，不是调参能完全抹平的。全局色彩校正只能处理分布差异，处理不了结构性细节缺失。</p>\n<p>第三，它不适用于低分辨率或显存充裕的场景。tile 越小显存越省，但重叠区占比随之升高，融合计算与显存拷贝开销会抵消显存收益。当整图激活本来就不构成压力时，引入分块只是白白增加重叠计算和接缝风险。规模上限受两个因素约束：单 tile 感受野必须足够覆盖解码器的有效上下文，融合权重设计必须能压住边界跳变。</p>\n<ul>\n<li>不解决：去噪阶段激活瓶颈、跨阶段流水编排、KV 缓存压力（本方法无需 KV 缓存）。</li>\n<li>不解决：tile 边界的高频细节一致性，只能缓解不能根治。</li>\n<li>不解决：极小 tile 下的算力浪费问题，重叠占比是硬约束。</li>\n</ul>\n\n<h3 id=\"alg-vae-tile-decode-sec-4\">四 · 代价结构：用重叠计算换显存</h3>\n<p>与整图解码相比，本方法的交易非常明确：以重叠计算换显存。重叠区被至少两个 tile 各解码一次，融合再做一次加权求和，额外算力大致与重叠带宽占 tile 面积的比例成正比。这笔账在显存受限时是划算的——整图解码根本跑不起来，重叠开销再大也是从“不可行”到“可行”的跨越；但在显存充裕时就是纯亏损。</p>\n<p>显存侧还有一笔容易被忽略的成本：tile 激活的释放与写回节奏。逐 tile 解码、写回、释放的循环如果与多 stream 并行叠加，同时活跃的 tile 数决定了实际峰值——不是单 tile 显存，而是“并发 tile 数 × 单 tile 显存”。多 stream 提升时延的同时会抬高这个乘积，调度器必须给并发 tile 数设上限，否则分块省下来的显存又被并行度吃回去。带宽侧，输出缓冲的全图写回与重叠区的重复读写构成额外流量，FP16 解码把这份流量减半，kernel 融合则减少中间张量的往返。</p>\n<p>具体例子：2048² 图像按固定 tile 切分并留重叠边界，若并发 4 个 tile 解码，峰值显存约为 4 倍单 tile 激活加模型权重；把并发降到 2 并配合 FP16 与 kernel 融合，峰值显存回到单卡舒适区，代价是解码时延不再随 tile 数线性下降。这就是负载配方里“批大小按单 tile 显存上限设定”的实际含义——批与并发 tile 数共享同一个显存预算。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-5\">五 · 失败模式：色带、断裂与反向收益</h3>\n<p>最典型的失败是重叠区权重设计不当。$\\sigma$ 取得过小，权重在边界附近衰减过快，融合退化为近似硬拼接，tile 边界出现色带或亮度跳变；$\\sigma$ 取得过大，远处 tile 的贡献被不合理放大，边界附近出现模糊。更麻烦的是这类色带难以用全局校正完全消除——收尾的色彩/亮度一致性校正处理的是 tile 间整体分布差异，对局部权重失配造成的周期性条纹无能为力。</p>\n<p>第二类失败是感受野截断导致的高频不一致。文字与细纹理在 tile 边界处断裂，视觉上是“接缝处突然糊掉”。这类问题的根源不在融合权重，而在每个 tile 解码时缺少跨边界的上下文，增加重叠像素只能缓解，不能消除。工程判断是：对文字密集或纹理精细的输出，要么加大重叠、要么放弃分块改走整图或更大显存的路径。</p>\n<p>第三类失败是 tile 过小导致的反向收益。重叠区占比升高后，融合计算与显存拷贝开销上升，同时并发 tile 数受显存预算约束无法提高，最终显存省了一点、时延反而变长。这类失败在调参时最容易被误判为“分块没用”，实际是 tile 尺寸与并发度没有联合调优。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>触发条件</th><th>系统代价</th><th>工程对策</th></tr></thead><tbody><tr><td>边界色带/亮度跳变</td><td>$\\sigma$ 与重叠带宽失配</td><td>画质返工、重解码时延</td><td>按重叠宽度标定 $\\sigma$，保留全局校正</td></tr><tr><td>高频细节断裂</td><td>tile 边界感受野截断</td><td>文字/纹理区域不可用</td><td>加大重叠或对细节区域走整图</td></tr><tr><td>反向收益</td><td>tile 过小、重叠占比高</td><td>融合算力与拷贝开销抵消显存收益</td><td>tile 尺寸与并发 tile 数联合调优</td></tr></tbody></table>\n<p>把这三类失败放回事故现场看，分块解码的适用边界就清楚了：它是一把针对“峰值显存由全图决定”这一特定病灶的手术刀，刀口之外的问题——去噪激活、跨阶段编排、细节一致性——它既不动也不该动。部署时的硬件档位按单 tile 峰值显存选卡，并行拓扑走 tile 级多 stream，量化走 FP16 解码配合 kernel 融合，这套配方成立的前提始终是：瓶颈确实在解码期的全图激活上。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-6\">六 · 显存墙下的解码失败：分块并行能救什么、救不了什么</h3>\n<p>线上事故的形态很具体：一条高分辨率出图链路在高峰期批量提交 2048² 图像，单张解码的激活峰值可达数十 GB，与权重、输出缓冲叠加后把单卡显存顶满，调度器被迫把请求串行化甚至回退到低分辨率，端到端吞吐骤降。注意这不是去噪阶段的显存问题——去噪计算图未变，问题只出在 VAE 解码期：解码器在上采样路径上逐级放大特征图，激活随空间尺寸平方增长，而整图一次性解码意味着峰值必须容纳全图所有中间层。分块并行解码正是针对这一点的空间切块方案，它把峰值压到单 tile 量级：<div class=\"formula\">$$\\text{Mem}_{\\text{peak}}\\approx \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}$$</div>代价是用重叠计算换显存，因此它解决的是“单卡装不下整图激活”，而不是“解码算力不够”。</p>\n<p>它的失效条件同样清晰。其一，tile 边界处感受野被截断，解码器看不到邻域上下文，文字、细纹理与高频边缘会出现断裂，全局校正无法真正复原被截掉的信息；其二，融合权重设计不当会在重叠区留下色带或亮度跳变，且这种误差沿 tile 网格呈周期性分布，比随机噪声更难掩盖。用高斯距离权重时融合式为<div class=\"formula\">$$\\hat{x}(u)=\\frac{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)\\,D_i(u)}{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)},\\quad w_i(u)=\\exp\\left(-\\frac{\\|u-c_i\\|_2^2}{2\\sigma^2}\\right)$$</div>其中 $\\sigma$ 过小则接缝明显，过大则中心区域被邻块稀释、细节发软——这是一个没有普适最优解的调参面。其三，tile 过小时重叠区占比升高，融合计算与显存拷贝开销会抵消显存收益，规模上限受单 tile 感受野与权重设计共同约束。</p>\n<p>系统代价要按账算清楚。显存侧收益是决定性的：2048² 解码从“数十 GB、单卡不可行”降到单 tile 峰值，配合 FP16 解码与 kernel 融合进一步压低峰值，使单卡完成成为默认路径；时延侧 tile 间可并行，多 stream 下解码时延随 tile 数近线性下降，但重叠区带来额外计算量，tile 数越多总算力越高于整图解码；带宽侧每个 tile 的输出都要写回输出缓冲并做重叠区读写，融合阶段是一次额外的全局访存。适用边界因此可归纳为：请求形态是高分辨率单图或批量图、SLO 以解码时延为主、显存而非算力是瓶颈的场景；反之，若分辨率不高、整图解码已能装下，或对像素级一致性要求极高（如医学影像拼接），分块引入的接缝风险与额外算力就不划算。它与阶段级流水、patch 级调度的区别也在于此：只在 VAE 解码期切空间，不改去噪计算图。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>分块并行是否适用</th><th>主因</th></tr></thead><tbody><tr><td>2048²、整图激活数十 GB</td><td>适用</td><td>峰值降到单 tile，单卡可完成</td></tr><tr><td>低分辨率、整图可容纳</td><td>不适用</td><td>重叠计算纯属额外开销</td></tr><tr><td>文字/细纹理密集、要求像素一致</td><td>慎用</td><td>感受野截断导致高频断裂</td></tr><tr><td>tile 取得过小</td><td>失效</td><td>重叠占比高，收益被拷贝与融合抵消</td></tr></tbody></table>\n<h3 id=\"alg-vae-tile-decode-sec-7\">七 · 切分：从 latent 网格到带重叠的 tile 集合</h3>\n<p>解码期的第一步不是算，而是切。输入是形状为 <code>[B, C, H_l, W_l]</code> 的高分辨率 latent，输出是一组 tile 描述符，每个描述符携带三样东西：latent 上的源矩形、输出画布上的目标矩形、以及该 tile 在重叠区内的权重图。切分的粒度由单 tile 激活上限反推——先定下这张卡在 FP16 解码时能承受的激活峰值，再除以 VAE 解码器逐层放大的系数，得到 tile 的空间边长。2048² 图像在整图解码时激活可占数十 GB，正是这个数字把 tile 边长压到远小于全图的尺度。</p>\n<p>边界重叠像素的宽度不是随手取的常数，它必须覆盖解码器最深的有效感受野。VAE 解码器由若干上采样阶段堆叠，每个阶段的卷积核在输出分辨率上贡献一段感受野；重叠宽度若小于该感受野，tile 中心区域的输出才是可信的，边缘一圈必然被截断。工程上把重叠宽度取为感受野的整数倍，并让权重带宽 σ 与之匹配，使衰减在到达 tile 硬边界前已降到可忽略。</p>\n<p>这一步的代价是显存与拷贝，而不是算力。切分本身只产生索引与权重图，权重图按 tile 存储，尺寸为重叠区面积乘以通道数，用 FP16 存放；对 2048²、tile 数上百的配置，权重图总量与单 tile 激活同量级，必须计入 <code>Mem_tile</code> 预算。更隐蔽的代价是源 latent 的重复读取：每个 tile 都要把自己那份带重叠的 latent 切片搬进显存，重叠区被相邻 tile 各读一次，读放大系数等于 1 加上重叠占比。tile 越小，这个系数越接近线性膨胀，这正是“tile 过小则重叠占比高、算力浪费”的量化来源。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-8\">八 · 逐 tile 解码：把激活峰值锁死在单 tile 内</h3>\n<p>每个 tile 独立走一遍完整的解码器前向。输入是该 tile 的 latent 切片，输出是该 tile 在目标画布上的 FP16 特征图。关键约束是：解码器中间层的激活不得跨 tile 存活。实现上，每个 tile 的前向在一个独立的显存工作区内完成，工作区大小按最胖的中间层预留，前向结束后特征图被搬到输出缓冲，工作区立即复用给下一个 tile。峰值显存因此满足</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{peak}}\\approx \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}$$</div>\n<p>其中 <code>Mem_model</code> 是解码器权重，与 tile 数无关；<code>Mem_tile</code> 是单 tile 工作区加权重图。整图解码时 <code>Mem_tile</code> 随 H_l·W_l 平方增长，分块后它被钉在一个常数上——这是本方法全部收益的来源，也是它唯一不能妥协的约束。</p>\n<p>逐 tile 解码的另一个工程要点是 kernel 融合。解码器里连续的上采样、归一化、激活若各自落盘中间张量，单 tile 内的峰值会被这些临时缓冲抬高数倍；把相邻算子融成一次写回，能让 <code>Mem_tile</code> 只保留融合边界上的张量。配合 FP16 解码，权重与激活都走半精度，既压低了工作区字节数，也让 tensor core 的吞吐跑满。代价在延迟侧：单 tile 前向的算力利用率受 tile 边长限制，边长过小时矩阵乘的 M/N 维退化，tile 内并行度不足以喂满 SM，单 tile 时延不再随面积线性缩放。这是分块解码在小 tile 区间必然遇到的效率拐点。</p>\n<p>举例：一个 2048² 输出、tile 边长取全图的四分之一、重叠宽度覆盖最深感受野的配置，tile 数为十余个量级；每个 tile 的工作区按最胖中间层预留，整卡峰值由最大那个 tile 决定，而非由全图决定。批处理时，批大小按单 tile 显存上限设定，而不是按整图上限设定——这是负载配方里最容易被忽略的一条。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-9\">九 · 重叠区融合：按距离加权的线性叠加</h3>\n<p>融合发生在输出缓冲上，输入是各 tile 已解码的特征图与对应权重图，输出是消除了接缝的整图。像素 <code>u</code> 可能被多个 tile 覆盖，融合公式为</p>\n<div class=\"formula\">$$\\hat{x}(u)=\\frac{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)\\,D_i(u)}{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)},\\quad w_i(u)=\\exp\\left(-\\frac{\\|u-c_i\\|_2^2}{2\\sigma^2}\\right)$$</div>\n<p>其中 <code>D_i(u)</code> 是第 i 个 tile 的解码结果，<code>N(u)</code> 是覆盖 u 的 tile 集合，<code>c_i</code> 是 tile 中心，σ 是重叠区权重带宽。分母的归一化是必须的：tile 在画布边缘处覆盖数不足，若不归一化，边缘像素的亮度会按覆盖数成比例塌陷。高斯权重让靠近 tile 中心的像素占主导，靠近硬边界的像素被压低，从而把“边界处感受野截断”的误差压到权重趋零的区域。</p>\n<p>这一步的代价是三重叠加。第一重是额外计算：重叠区被解码两次以上，融合再做一次加权求和，重叠占比直接乘在解码算力上。第二重是带宽：每个 tile 的特征图都要写进输出缓冲再被读出做融合，重叠区的特征图被读写多遍，HBM 流量随重叠占比上升。第三重是精度：FP16 下加权求和的累加若在低精度完成，重叠区会出现舍入导致的亮度台阶，因此累加通常在 FP32 累加器里做，再把结果舍入回 FP16 写回。σ 的选择是精度与接缝的折中——σ 太小，权重在边界处骤降，融合退化为硬拼接，色带立刻出现；σ 太大，远处 tile 的截断误差被抬进中心区，高频细节被抹平。</p>\n<p>失败模式在这里最集中：权重设计不当会在 tile 边界产生色带或亮度跳变，且难以用全局校正完全消除；文字与细纹理处因边界感受野截断出现断裂，融合只能压低其幅度而不能恢复被截断的高频。判断标准很直接——把 σ 减半重跑，若接缝显著恶化，说明重叠宽度本就不足，问题不在权重而在切分。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-10\">十 · 写回与释放：输出缓冲的生命周期</h3>\n<p>每个 tile 解码完成后立刻做两件事：把特征图按目标矩形写进输出缓冲的对应位置，然后释放该 tile 的工作区与权重图。写回是带偏移的块拷贝，源是 tile 的连续特征图，目标是输出缓冲的子矩形，行跨度不等于 tile 宽度，因此拷贝按行分片进行，行数等于 tile 输出高度。这一步的带宽代价与 tile 输出字节数成正比，且与融合阶段的读回叠加——同一块重叠区特征图在生命周期内至少被写一次、读两次。</p>\n<p>输出缓冲本身是整图尺寸的 FP16 张量，它不属于 <code>Mem_tile</code>，而是独立于 tile 数存在的固定开销。对 2048² 输出，这块缓冲的字节数按通道数乘以面积计算，虽远小于整图解码的激活峰值，但在多请求并发时必须按并发数复制，容量规划要把这一项单列。释放的时机决定峰值：若等全部 tile 完成再统一释放，工作区会随 tile 数累积，分块的意义被抵消；正确做法是每个 tile 前向一结束就归还工作区，使 <code>Mem_tile</code> 始终等于单个 tile 的瞬时占用。</p>\n<p>多 stream 并行时，写回与释放的顺序需要同步原语保护：相邻 tile 的重叠区在输出缓冲上是同一片地址，两个 stream 同时写会产生竞争。工程上用 tile 级的完成事件串起融合顺序，让重叠区的写回按 tile 索引单调推进，从而把竞争消解为确定性的覆盖顺序。代价是并行度被重叠关系局部串行化——不重叠的 tile 可以全速并行，重叠的相邻 tile 必须等前者写回完成。这解释了为什么“tile 间可并行，多 stream 下解码时延随 tile 数近线性下降”只在重叠占比低时成立。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-11\">十一 · 全局一致性校正：一次收尾的分布对齐</h3>\n<p>全部 tile 完成后，输出缓冲上做一次色彩与亮度的一致性校正。输入是整图 FP16 特征图，输出是同形状的校正结果。校正的动机是 tile 间分布差异：每个 tile 独立解码，其激活统计量（均值、方差）只反映本 tile 的内容，相邻 tile 若内容分布不同，边界两侧会出现系统性偏移，这种偏移是融合权重压不下去的——它不是高频截断，而是低频漂移。</p>\n<p>实现上，校正按 tile 网格分块统计，对每个 tile 计算其与全图统计量的偏差，再在 tile 边界带内做线性插值补偿，使补偿量在 tile 中心为零、在边界处取相邻 tile 偏差的加权平均。这一步的计算量相对解码可忽略，代价主要在访存：需要把整图读一遍算统计、再读一遍做补偿，两次全图 HBM 往返。对 2048² 的 FP16 输出，这是数十 MB 量级的流量，与解码阶段的算力相比不构成瓶颈，但在 SLO 以解码时延为主的场景里，它被计入端到端时延的固定尾巴，不能省。</p>\n<p>校正的边界很明确：它能消除 tile 间的低频漂移，不能修复被截断的高频细节，也不能挽救权重设计错误造成的色带。把校正当成接缝的万能补丁是常见的误判——校正只处理“分布不一致”，不处理“信息缺失”。因此校正的强度应当保守，补偿量设上限，避免把真实的图像梯度当成 tile 偏差抹掉。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-12\">十二 · 步骤间的代价传导与配方选择</h3>\n<p>把五步串起来看，代价沿数据流单向传导：切分决定的 tile 边长与重叠宽度，同时决定了单 tile 算力效率、重叠算力放大系数、融合带宽、以及感受野截断的严重程度。四个量互相拉扯，没有全局最优，只有按 SLO 取向的配方。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入 → 输出</th><th>主导代价</th><th>失效信号</th></tr></thead><tbody><tr><td>切分</td><td>latent → tile 描述符 + 权重图</td><td>权重图显存、latent 读放大</td><td>重叠占比过高，算力浪费</td></tr><tr><td>逐 tile 解码</td><td>tile latent → tile 特征图</td><td>单 tile 工作区、tile 内并行度</td><td>tile 过小，矩阵乘维度退化</td></tr><tr><td>重叠融合</td><td>多 tile 特征图 → 无缝像素</td><td>重叠算力、HBM 读写、FP32 累加</td><td>σ 失配，色带或细节抹平</td></tr><tr><td>写回释放</td><td>tile 特征图 → 输出缓冲</td><td>块拷贝带宽、重叠区写竞争</td><td>释放滞后，峰值随 tile 数累积</td></tr><tr><td>一致性校正</td><td>整图 → 校正整图</td><td>两次全图 HBM 往返</td><td>补偿过量，抹掉真实梯度</td></tr></tbody></table>\n<p>配方选择因此落在两个旋钮上：tile 边长与重叠宽度。显存受限优先时，压 tile 边长、保重叠宽度覆盖感受野，接受重叠算力放大；时延受限优先时，放大 tile 边长以提高 tile 内并行度，把峰值显存推高到 <code>Mem_tile</code> 允许的上沿。批大小按单 tile 显存上限设定，而不是按整图上限设定；硬件档位按单 tile 峰值显存选卡，2048² 解码可在单卡完成，无需 KV 缓存，也无需跨卡切分解码器。多 stream 的并行拓扑只在重叠占比低时兑现近线性时延下降，重叠区的写回顺序是并行的硬约束。真正决定这套机制能否跑稳的，不是融合公式的精度，而是重叠宽度是否真的覆盖了最深感受野——这一条在切分阶段定下，后面四步都只是在它的约束内做补救。</p>\n<h3 id=\"alg-vae-tile-decode-sec-13\">十三 · 峰值显存公式：从全图激活到单 tile 上界</h3>\n<p>分块解码的第一条公式不是融合公式，而是显存上界公式：<span class=\"formula\">$$\\text{Mem}_{\\text{peak}}\\approx \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}$$</span>。逐项拆开看，<em>Mem<sub>model</sub></em> 是 VAE 解码器权重与常驻缓冲，与输入分辨率无关，在 FP16 下由层数、通道数与卷积核尺寸决定，属于部署时一次性确定的常量；<em>Mem<sub>tile</sub></em> 才是随分辨率变化的那一项，它包含单个 tile 在解码器各层产生的中间激活、上采样阶段的通道展开缓冲，以及写回输出缓冲时的一块临时目标区域。整图解码时 <em>Mem<sub>tile</sub></em> 被替换为 <em>Mem<sub>full</sub></em>，后者随像素数近似线性增长——2048² 图像解码可占数十 GB，正是这一项失控的结果。</p>\n<p>推导的关键一步在于：卷积解码器的激活峰值并不出现在输入层，而出现在最后一次上采样之后、输出卷积之前的那个高分辨率特征图上。设该层通道数为 <em>C</em>、空间边长为 <em>s</em>、数据类型字节数为 <em>b</em>，则该层激活为 <em>C·s²·b</em>；若整图边长 <em>S</em> 被切成边长 <em>t</em> 的 tile，则峰值按 <em>(t/S)²</em> 缩小。这就是分块能救显存的全部数学理由——它把二次方的空间项从全图规模压到 tile 规模，而权重项不变。工程判断由此而来：tile 尺寸的选择本质是在 <em>Mem<sub>tile</sub></em> 与重叠开销之间取平衡，而不是越小越好。</p>\n<p>代价侧要算清两笔账。第一笔是重叠计算：若 tile 边长 <em>t</em>、重叠带宽 <em>o</em>，则有效覆盖率为 <em>(t−o)²/t²</em>，重叠占比随 <em>t</em> 减小而平方级上升，tile 过小会使融合计算与显存拷贝开销抵消显存收益。第二笔是写回带宽：每个 tile 解码完成后要把结果写入全图输出缓冲，写回量正比于 tile 面积乘以覆盖 tile 数，重叠区被重复写入。以 2048²、FP16 三通道输出为例，单张输出缓冲本身已是数十 MB 量级，重复写入在 tile 数多时会显著抬高 HBM 流量，因此在多 stream 并行时必须让写回与下一 tile 的计算重叠，否则带宽成为新瓶颈。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-14\">十四 · 加权融合公式：距离权重与归一化分母</h3>\n<p>融合公式为 <span class=\"formula\">$$\\hat{x}(u)=\\frac{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)\\,D_i(u)}{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)},\\quad w_i(u)=\\exp\\left(-\\frac{\\|u-c_i\\|_2^2}{2\\sigma^2}\\right)$$</span>。逐项解释：<em>u</em> 是输出图上的像素坐标；<em>D<sub>i</sub>(u)</em> 是第 <em>i</em> 个 tile 解码器在 <em>u</em> 处的输出值，只有当 <em>u</em> 落在该 tile 的覆盖范围内时才有定义；<em>N(u)</em> 是覆盖 <em>u</em> 的 tile 集合，在规则网格加固定重叠的切分下，内部像素只被一个 tile 覆盖（此时公式退化为直接取值），只有重叠带上的像素才进入求和；<em>c<sub>i</sub></em> 是 tile 中心；<em>σ</em> 是权重带宽，控制权重随距离衰减的快慢。</p>\n<p>推导的关键一步是归一化分母的存在理由。高斯权重之和在重叠带内不等于 1，若直接加权求和而不除分母，重叠区亮度会被系统性抬高，形成可见的亮带；除以 <em>Σw<sub>i</sub></em> 相当于在每一点做一次凸组合，保证融合结果是各 tile 输出的加权平均，从而在常数输入下严格保持原值。这一步也解释了为什么权重必须为正：负权重会破坏凸组合性质，在边界产生振铃。</p>\n<p>σ 的取值直接决定接缝风险。σ 过大时权重在重叠带内近乎均匀，两侧 tile 各占一半，感受野截断导致的高频差异被平均成模糊带；σ 过小时权重迅速偏向本 tile 中心，边界处出现一阶不连续，表现为色带或亮度跳变。合理做法是让 σ 与重叠带宽 <em>o</em> 同量级，使权重在重叠带两端衰减到相近量级，融合过渡平滑。需要强调的是，权重设计不当产生的色带难以用全局校正完全消除——全局校正只能拉平整体色彩分布，无法修复逐像素的加权失配，因此 σ 与 <em>o</em> 的匹配必须在融合阶段就定好。</p>\n<p>系统代价方面，融合本身是逐像素的乘加与除法，计算量正比于重叠带面积乘以覆盖 tile 数，在 FP16 下可由融合 kernel 与解码 kernel 尾部合并完成，避免额外的全图读写往返。若把融合拆成独立 pass，则要多一次读输出缓冲、一次写输出缓冲，HBM 流量翻倍，在 tile 数多、重叠占比高时这部分开销不可忽略。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-15\">十五 · 感受野截断：为什么边界细节会不一致</h3>\n<p>分块解码的误差来源不是数值精度，而是感受野截断。VAE 解码器由多层卷积与上采样构成，输出像素 <em>u</em> 的值依赖输入 latent 上一个有限半径 <em>R</em> 内的区域，<em>R</em> 由各层卷积核尺寸与上采样倍率累乘决定。当 tile 边界切在 <em>u</em> 的感受野之内时，该 tile 在 <em>u</em> 处看到的输入上下文不完整，解码结果与整图解码在该点的结果产生偏差；重叠带的作用正是让边界像素至少有一个 tile 能提供完整感受野。</p>\n<p>由此得到一条可实现的约束：重叠带宽 <em>o</em> 必须不小于解码器的有效感受野半径 <em>R</em>（以输出像素计），否则无论权重怎么设计，边界处的高频细节都会断裂。文字与细纹理是最敏感的检验对象，因为它们的能量集中在高频，截断造成的相位偏移在融合后表现为笔画错位或纹理撕裂。工程上应把 <em>o</em> 设为 <em>R</em> 的保守上界，再在此基础上有余量地增加若干像素以容纳权重过渡。</p>\n<p>代价是显式的：<em>o</em> 增大直接抬高重叠占比，融合计算与重复写回同步上升；而 <em>o</em> 不足则高频不一致无法靠后处理补救。这是一个不能用“调参”糊过去的硬约束——它由网络结构决定，属于部署前就必须算清的常量。对于视频帧解码，同一约束逐帧成立，且帧间若做时间维融合还需额外考虑帧边界的时间感受野。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-16\">十六 · 伪代码：可落地的 tile 循环与融合写回</h3>\n<p>下面给出与公式一一对应的实现骨架，重点在缓冲复用与释放时机，而非框架 API。</p>\n<ul>\n<li>预分配全图输出缓冲 <em>Out</em>（FP16，形状 H×W×C）与权重累加缓冲 <em>Wsum</em>（同形状，或仅重叠带），二者常驻，不随 tile 数增长。</li>\n<li>对每个 tile 索引 <em>i</em>：从 latent 切出带重叠的输入块，送入解码器，得到 <em>D<sub>i</sub></em>；此步激活峰值被限制在单 tile 内。</li>\n<li>对 <em>D<sub>i</sub></em> 覆盖的每个像素 <em>u</em>：计算 <em>w<sub>i</sub>(u)=exp(−‖u−c<sub>i</sub>‖²/2σ²)</em>，执行 <em>Out[u] += w<sub>i</sub>(u)·D<sub>i</sub>(u)</em> 与 <em>Wsum[u] += w<sub>i</sub>(u)</em>。</li>\n<li>写回完成后立即释放 <em>D<sub>i</sub></em> 及其激活，进入下一 tile；多 stream 下该释放与下一 tile 的计算可重叠。</li>\n<li>全部 tile 完成后做一次逐像素归一化 <em>Out[u] /= Wsum[u]</em>，随后执行一次色彩/亮度一致性校正。</li>\n</ul>\n<p>这个骨架有两个易错点。其一，若把归一化放在每个 tile 写回时做，则后续 tile 的累加会破坏已归一化的值，必须把除法推迟到全部 tile 完成之后，这正是公式中分母写成对 <em>N(u)</em> 求和而非逐 tile 归一的原因。其二，<em>Wsum</em> 若与 <em>Out</em> 同尺寸常驻，会额外占用一份全图缓冲的显存；在显存吃紧时可只对重叠带维护稀疏的权重累加，内部像素直接赋值跳过融合，从而把融合开销压到重叠面积量级。</p>\n<p>吞吐侧，tile 间无数据依赖（除写回缓冲的原子累加外），可映射到多 stream 并行；解码时延随 tile 数近线性下降的前提是每个 stream 的激活峰值之和仍低于显存上限，因此并行度应由 <em>Mem<sub>tile</sub></em> 与卡上可用显存共同决定，而不是取最大 stream 数。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-17\">十七 · 收尾校正与失败模式的量化视角</h3>\n<p>全部 tile 完成后的色彩/亮度一致性校正，处理的是 tile 间分布差异而非逐像素加权失配。其必要性来自解码器对输入块统计量的隐式依赖：不同 tile 的 latent 局部均值与方差略有差异，解码后在整体色调上留下可测的偏移，融合只能平滑过渡带，无法消除块内的系统性偏色。校正通常以全图统计量为基准对每个 tile 区域做低阶（增益/偏置）映射，计算量正比于像素数，属于一次轻量 pass。</p>\n<p>把失败模式折算成代价可以更清楚地做取舍。色带与亮度跳变源于 σ 与 <em>o</em> 失配，修复方式是增大 <em>o</em> 或重设 σ，代价是重叠占比上升；高频断裂源于 <em>o &lt; R</em>，修复方式是增大 <em>o</em>，代价同上；tile 过小导致的算力浪费表现为融合与拷贝开销超过显存收益，其判据是重叠占比 <em>(t−o)²/t²</em> 的下降幅度是否已抵消 <em>Mem<sub>tile</sub></em> 的节省。三者共同指向一个工程判断：tile 尺寸与重叠带宽应在满足 <em>o ≥ R</em> 的前提下取使 <em>Mem<sub>tile</sub></em> 刚好落入显存预算的最大 <em>t</em>，把剩余预算留给多 stream 并行度，而不是一味缩小 tile。</p>\n<p>最后落到可实现的一步：融合 kernel 应与解码 kernel 的尾部融合，使 <em>D<sub>i</sub></em> 在寄存器或共享内存中直接参与加权累加，避免先写回再读回的往返；这一步同时降低了峰值显存与 HBM 流量，是 FP16 解码配合 kernel 融合在分块场景下的具体落点。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-18\">十八 · 重叠融合的失效边界与 tile 尺寸的代价曲线</h3>\n<p>核心公式的第二项才是这套方案真正的风险所在：$\\hat{x}(u)=\\sum_{i\\in\\mathcal{N}(u)} w_i(u)D_i(u)/\\sum_{i\\in\\mathcal{N}(u)} w_i(u)$，其中 $w_i(u)=\\exp(-\\|u-c_i\\|_2^2/2\\sigma^2)$。推导的关键一步在于把“接缝”理解为相邻 tile 在同一像素上的预测差异 $\\Delta_{ij}(u)=D_i(u)-D_j(u)$，融合后残差为 $\\sum_i w_i\\Delta_{i,\\text{ref}}(u)/\\sum_i w_i$——也就是说，权重只能压低差异，不能消除差异。当 $\\sigma$ 取得过小，权重在重叠区中段迅速衰减，$\\Delta$ 几乎原样保留，边界出现色带或亮度跳变；当 $\\sigma$ 取得过大，权重趋于均匀，融合退化为算术平均，高频细节被平滑掉。更棘手的是，这类色带由 tile 间的分布偏移造成，收尾的色彩/亮度一致性校正只能拟合全局仿射量，无法修复沿边界的局部跳变。</p>\n<p>第二个失效条件是感受野截断。VAE 解码器的每个输出像素依赖有限感受野内的 latent，tile 边界处的像素只能看到被裁掉一半的邻域，其解码结果与整图解码在统计上不同。这在文字、细纹理、锐利边缘处表现为断裂而非模糊——因为截断丢失的是高频相位信息，融合权重对相位误差无能为力。工程上的判断是：重叠像素宽度必须不小于解码器有效感受野半径，否则无论权重怎么调，边界都会残留结构不一致。</p>\n<p>代价曲线由重叠占比决定。设 tile 边长 $T$、重叠宽度 $o$，则重叠面积占比约 $1-(T-o)^2/T^2$，融合计算量与显存拷贝量随之上升。tile 过小时，单 tile 激活虽降，但重叠区占比升高，融合的读写带宽开销与多 stream 调度开销会抵消显存收益，甚至因输出缓冲的反复写回而拖慢端到端时延。可用下表做粗判：</p>\n<table class=\"mini\"><thead><tr><th>tile 尺寸倾向</th><th>峰值显存</th><th>重叠开销</th><th>主要风险</th></tr></thead><tbody><tr><td>偏大</td><td>接近全图，收益有限</td><td>低</td><td>单卡放不下，退化为整图解码</td></tr><tr><td>适中</td><td>限制在单 tile 激活内</td><td>可控</td><td>需按感受野定重叠宽度</td></tr><tr><td>偏小</td><td>最低</td><td>占比高，拷贝与融合主导</td><td>色带、细节断裂、算力浪费</td></tr></tbody></table>\n<p>因此伪代码里必须显式约束三件事：重叠宽度由感受野而非经验常数决定；$\\sigma$ 与重叠宽度绑定（通常取重叠区半宽量级），使权重在边界处平滑过渡到零；每个 tile 解码后立即写回输出缓冲并释放激活，把峰值显存钉在 $\\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}$ 上，配合 FP16 解码与 kernel 融合压缩单 tile 占用。2048² 图像从数十 GB 的全图激活降到单卡可容纳的量级，代价是重叠区的额外算力与一次全局校正；当 tile 数增加使时延随多 stream 近线性下降时，真正的瓶颈会从显存转移到融合带宽与调度粒度上。</p>\n<h3 id=\"alg-vae-tile-decode-sec-19\">十九 · 请求形态的匹配面：什么负载落在配方里</h3>\n<p>分块并行解码的负载配方不是“任何 VAE 解码都适用”，而是一条有明确边界的曲线。落在曲线内的请求形态有三个共同特征：latent 空间分辨率高到整图解码激活会突破单卡显存、单次请求的解码时延由 SLO 直接约束、以及请求到达率不足以让整图解码的显存峰值被批内多请求摊薄。2048² 图像解码占数十 GB 激活这一事实，决定了整图路径在单卡上根本不可调度；此时分块不是优化选项，而是可行性前提。反过来，若请求是 512² 级的小图，整图解码的激活峰值远低于显存上限，分块引入的重叠计算与融合开销纯属净损失，配方应直接判定为不适用。</p>\n<p>长度分布在这里指 latent 的边长分布而非序列长度。配方对分布的敏感点在于长尾：若 90% 请求是 1024²、10% 是 2048²，按 2048² 选 tile 大小会让小图请求的 tile 数偏少、重叠占比偏高；按 1024² 选 tile 又会让大图请求的 tile 数翻倍、单请求时延拉长。工程上的处理是把 tile 大小做成随 latent 边长缩放的函数，使 tile 数维持在一个窄区间内，而不是固定像素尺寸。这一条直接决定了下游批大小与并发度的可预测性。</p>\n<p>并发与批大小的配方核心是“批按 tile 而非按请求”。设单 tile 解码的激活峰值为 $\\text{Mem}_{\\text{tile}}$，模型常驻为 $\\text{Mem}_{\\text{model}}$，则单卡可同时驻留的 tile 数 $B_{\\text{tile}}$ 满足</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{peak}}\\approx \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}},\\qquad B_{\\text{tile}}\\le\\frac{\\text{Mem}_{\\text{budget}}-\\text{Mem}_{\\text{model}}}{\\text{Mem}_{\\text{tile}}}$$</div>\n<p>批大小按 $B_{\\text{tile}}$ 设定，而不是按请求数设定。一个 2048² 请求切成 $N$ 个 tile 后，它占用的是 $N$ 份 tile 预算中的若干份；多请求并发时，调度器把不同请求的 tile 混在同一批里送入解码器，批内 tile 彼此独立，这正是 tile 间可并行、多 stream 下解码时延随 tile 数近线性下降的来源。代价是批内 tile 来自不同图像时，融合阶段必须按请求维度回收输出缓冲，写回逻辑比单请求复杂一档。</p>\n<p>具体例子：一张 2048² latent 按 256 像素 tile、32 像素重叠切分，横向与纵向各约 9 块，总计约 81 个 tile；若单 tile 激活峰值使 $B_{\\text{tile}}$ 落在 8 至 16 之间，则该请求需要 5 至 10 个批次才能解完。此时单请求时延约等于批次数乘以单批解码时间，而吞吐由批内 tile 填满率决定。填不满的批次是配方失效的第一信号。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-20\">二十 · 批内 tile 混排的调度机制与填谷代价</h3>\n<p>配方要求调度器以 tile 为粒度做连续批处理，而不是以请求为粒度做静态批。机制上分三步：请求进入时先做 latent 切分并生成 tile 描述符（请求 id、tile 坐标、重叠区标记），描述符入全局 tile 队列；调度器按 $B_{\\text{tile}}$ 从队列取 tile 组成批，优先取同一请求的相邻 tile 以提升融合局部性；批完成后 tile 结果写回该请求的输出缓冲并释放激活，队列继续填充。这套机制与连续批处理在 LLM 里的形态同构，但填充单位从 token 变成了 tile。</p>\n<p>填谷代价出现在请求尾部。一个请求的最后几个 tile 数量不足以填满一批时，调度器要么空跑（浪费算力），要么拉入下一请求的 tile（引入跨请求混批）。前者使有效吞吐下降，后者使融合阶段的缓冲管理变复杂。量化这一代价的指标是批填充率</p>\n<div class=\"formula\">$$\\eta_{\\text{fill}}=\\frac{\\sum_{b} n_b}{B_{\\text{tile}}\\cdot\\lceil T/B_{\\text{tile}}\\rceil}$$</div>\n<p>其中 $n_b$ 为第 $b$ 批实际 tile 数，$T$ 为队列中待处理 tile 总数。$\\eta_{\\text{fill}}$ 低于某阈值时，分块路径的吞吐优势被尾部空跑吃掉，此时应改为按请求整图解码（若显存允许）或调小 tile 以提高 tile 数、增加可混排粒度。</p>\n<p>系统代价上，tile 级混排把显存压力从“单请求峰值”转为“批内 tile 总峰值”，带宽压力则来自 tile 激活的反复写回与释放。每完成一批就要把结果写入输出缓冲，这一写回是纯带宽开销，与 tile 数成正比。若输出缓冲按请求整图尺寸预分配，写回是分散的；若按 tile 环形缓冲，则融合阶段需要跨批拼接。工程判断是：tile 数多、批次多时，写回带宽会成为仅次于解码计算的第二开销，配方应把输出缓冲设计成按请求整图预分配、tile 结果直接落位，避免二次拼接。</p>\n<p>例子：同一请求 81 个 tile、$B_{\\text{tile}}=16$ 时需 6 个批次，最后一批仅 1 个 tile，$\\eta_{\\text{fill}}$ 在该请求上约为 $81/(16\\times 6)\\approx 0.84$；若队列中恰有另一请求的 tile 可补位，填充率回升，但融合缓冲需同时持有两个请求的写回目标。这就是配方对并发度的隐性要求：并发请求数至少为 2 至 3，才能让尾部填谷有料可填。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-21\">二十一 · 长度分布偏移下的 tile 数与重叠占比</h3>\n<p>重叠占比是配方里最容易被低估的负载变量。设 tile 边长为 $s$、重叠宽度为 $o$，则一维有效步长为 $s-o$，重叠占比近似</p>\n<div class=\"formula\">$$\\rho_{\\text{ovl}}\\approx\\frac{2o}{s}-\\frac{o^{2}}{s^{2}}$$</div>\n<p>$\\rho_{\\text{ovl}}$ 直接乘在解码算力上：重叠区被两个相邻 tile 各解码一次，融合再做一次加权。tile 越小，$\\rho_{\\text{ovl}}$ 越大，融合计算与显存拷贝开销抵消显存收益，这正是“tile 过小则重叠占比高、算力浪费”的量化形态。配方对长度分布的要求是：latent 边长变化时，$s$ 随边长缩放而 $o$ 保持与感受野匹配的固定值，使 $\\rho_{\\text{ovl}}$ 落在可控区间；若 $o$ 也随 $s$ 缩放，小图请求的重叠占比会失控。</p>\n<p>长度分布偏移的另一种形态是极端长宽比。宽高比悬殊的 latent 切成方形 tile 后，短边方向的 tile 数很少，重叠区在短边上的占比被放大，接缝风险集中在该方向。配方应允许 tile 在长短边上取不同尺寸，或在短边方向减少重叠层数，代价是短边接缝的融合权重带宽 $\\sigma$ 需要单独标定。</p>\n<p>系统代价上，$\\rho_{\\text{ovl}}$ 升高直接抬高单请求的解码算力，进而抬高时延；在 SLO 以解码时延为主的场景里，这等于把时延预算消耗在重复计算上。带宽侧，重叠区的激活需要被两个 tile 分别持有并在融合时读取，峰值显存虽仍限制在单 tile 内，但融合阶段的读带宽随重叠面积线性上升。例子：$s=256$、$o=32$ 时 $\\rho_{\\text{ovl}}\\approx 0.23$；若把 $s$ 降到 128 而 $o$ 不变，$\\rho_{\\text{ovl}}$ 升到约 0.44，算力近乎翻倍而显存只省一半，配方在此处应判定为不划算。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-22\">二十二 · 负载不对时的三种失效形态</h3>\n<p>第一种失效是批过大导致的显存回溢。配方按 $B_{\\text{tile}}$ 设批，但 $B_{\\text{tile}}$ 的估算若只算了单 tile 激活而漏算融合阶段的中间缓冲与输出写回缓冲，实际峰值会突破预算。表现为批内 tile 数一升高就触发重调度或 OOM，吞吐骤降。机制上的修正是把融合缓冲计入 $\\text{Mem}_{\\text{peak}}$，并把 $B_{\\text{tile}}$ 按最坏 tile（重叠区最多、融合窗口最大）估算，而非按平均 tile。</p>\n<p>第二种失效是并发过低导致的填谷失败。并发请求数不足时，tile 队列长期处于“单请求尾部”状态，$\\eta_{\\text{fill}}$ 低，多 stream 的并行度上不去，解码时延不再随 tile 数近线性下降，而是被批次间隔主导。此时分块路径的时延优势消失，配方应回退到整图解码或提高并发准入。这一失效与负载的到达率直接相关：低到达率场景下，分块并行解码的收益被批调度开销吃掉。</p>\n<p>第三种失效是 tile 边界感受野截断在高频内容上暴露。文字、细纹理处，tile 边界两侧的解码结果因感受野不完整而出现断裂，融合权重无法完全消除。负载不对的形态是：请求内容以高频细节为主（如文档图像、纹理密集场景），而 tile 尺寸偏小、重叠不足。系统代价是质量返工或人工校正，属于隐性时延。配方对此的判断是提高重叠宽度或增大 tile，用算力换细节一致性；若 SLO 不允许，则应把这类请求路由到整图解码路径。</p>\n<p>三种失效的共同点是：它们都不表现为解码器本身变慢，而表现为调度层的指标异常——填充率、批次数、重调度次数。配方监控应盯这三个指标而非单 tile 解码时间。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-23\">二十三 · 配方参数与硬件档位的联动</h3>\n<p>硬件档位按单 tile 峰值显存选卡，这是配方的第一条联动规则。2048² 解码可在单卡完成的前提是 $\\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}$ 落在单卡预算内；若 tile 尺寸选得使单 tile 激活接近预算上限，则 $B_{\\text{tile}}$ 退化为 1，批内并行消失，多 stream 退化为串行 tile 解码，时延随 tile 数线性上升而非近线性下降。因此配方要求 tile 尺寸留出至少能容纳 2 至 4 个 tile 的显存余量，把并行度买回来。</p>\n<p>第二条联动是量化与 kernel 融合。FP16 解码配合 kernel 融合降低峰值显存，使同样的显存预算能容纳更多 tile 或更大的 tile。配方上这意味着：在 FP16 路径下，$B_{\\text{tile}}$ 的可用档位比未融合路径高一档，调度器可以按更高并发配置。代价是 FP16 的数值范围对 VAE 解码器的极端激活更敏感，融合权重在重叠区的线性叠加若在 FP16 下累加，需注意累加顺序，避免小权重被大权重吞掉。</p>\n<p>第三条联动是并行拓扑。tile 级多 stream 的拓扑要求解码器 kernel 对批内 tile 无跨 tile 依赖，这在 VAE 解码器里成立的前提是解码器本身不含全局归一化或跨空间注意力。若解码器含跨 tile 的全局操作，分块会破坏其语义，配方必须在该层退化为整图或改用近似。这一条是配方适用性的硬边界，与 tile 大小无关。</p>\n<p>例子：单卡预算下 $\\text{Mem}_{\\text{model}}$ 固定，若单 tile 激活使 $B_{\\text{tile}}=4$，则 81 个 tile 的请求需约 21 个批次；若通过 kernel 融合把单 tile 激活压低，$B_{\\text{tile}}$ 升到 8，批次减半，时延近半。配方参数（tile 尺寸、批大小、stream 数）应随这一联动一起调，而不是单独调批大小。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-24\">二十四 · 负载配方的工程判据</h3>\n<p>把上述收束成可执行的判据：请求 latent 边长使整图解码激活超过单卡预算、且请求内容不以跨 tile 全局操作为主，配方成立；在此前提下，tile 尺寸按“单 tile 激活留出 2 至 4 倍余量”选，重叠宽度按感受野与高频内容占比选，批大小按 $B_{\\text{tile}}$ 选，并发准入按“队列中常驻至少 2 至 3 个请求的 tile”设。任一条件不满足，分块路径的收益就被重叠算力、填谷空跑或质量返工吃掉。</p>\n<p>监控判据落在三个比值上：$\\eta_{\\text{fill}}$ 反映批调度是否吃饱，$\\rho_{\\text{ovl}}$ 反映算力是否被重叠浪费，单请求批次数反映时延是否被尾部拉长。三者同时健康时，分块并行解码的时延随 tile 数近线性下降才真正兑现；任一比值恶化，应先调 tile 尺寸与重叠宽度，再调批大小，最后才考虑换硬件档位。这条顺序的依据是：tile 尺寸同时影响显存、算力与融合质量，是配方里杠杆最长的参数。</p>\n<p>最后落在具体机制上：融合权重 $w_i(u)=\\exp(-\\|u-c_i\\|_2^2/2\\sigma^2)$ 的带宽 $\\sigma$ 是配方与质量的耦合点。$\\sigma$ 偏小，重叠区权重集中在 tile 中心附近，边界处两 tile 权重都低，融合结果对边界误差不鲁棒，易出色带；$\\sigma$ 偏大，权重在重叠区过于平坦，边界两侧的高频差异被平均成模糊。配方应把 $\\sigma$ 与重叠宽度 $o$ 绑定标定，使重叠区内权重从中心到边界单调衰减且两端不趋零，这是分块解码在负载配方层面唯一不能靠调批大小补救的质量参数。</p>\n<h3 id=\"alg-vae-tile-decode-sec-25\">二十五 · 硬件档位：以单 tile 峰值为选卡依据</h3>\n<p>部署这套解码器的第一决策不是“买最大的卡”，而是把单 tile 峰值显存作为选卡标尺。核心约束是 <span class=\"formula\">$$\\text{Mem}_{\\text{peak}}\\approx \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}$$</span> 其中 $\\text{Mem}_{\\text{tile}}$ 由 tile 空间尺寸、VAE 解码器在该分辨率下的中间激活通道数与 FP16 字节宽共同决定，$\\text{Mem}_{\\text{model}}$ 是解码器权重常驻部分。整图 2048² 解码可达数十 GB 量级，而切块后峰值被压到单 tile 内，这正是“2048² 可在单卡完成”的物理来源。选卡时先固定一个候选 tile 边长，实测该 tile 的激活峰值，再加上权重与融合缓冲，得到单卡下限；若下限已接近卡容量，说明 tile 偏大或 kernel 融合不足，应先调 tile 而不是升档。</p>\n<p>档位划分应按“单卡能否容纳 N 个并发 tile”来做，而不是按整卡算力。B200/B300 单卡容量足以让多个 tile 的激活同时驻留，此时瓶颈从显存转为解码器 GEMM 的算力与显存带宽；GB200/GB300 NVL72 机柜内单卡容量相近但卡间带宽充裕，适合把 tile 分散到多卡、以 NVLink 5 回传融合所需的边界带。工程判断是：单图低延迟场景优先单卡多 stream，把 tile 并发压在单卡容量内；批量高吞吐场景才考虑跨卡切 tile，因为跨卡后重叠区的加权融合要跨设备取数，回传量正比于重叠带面积而非整图，这是它能扩展的前提。</p>\n<p>具体例子：一张 2048² 图按 512 边长切块，含重叠后 tile 数在十余到二十余个量级，每个 tile 的 FP16 激活峰值远小于整图，单卡即可容纳数个 tile 并发。若把 tile 缩到 256，tile 数翻数倍而重叠占比上升，单卡容量虽更宽松，但融合与拷贝开销开始吃掉收益——这就是档位选择必须与 tile 尺寸联合标定的原因。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-26\">二十六 · 并行拓扑：tile 级多 stream 与融合的同步点</h3>\n<p>拓扑的最小单元是 tile，不是请求。每个 tile 走一条独立 stream，解码 kernel 在 stream 内顺序执行，stream 之间无数据依赖，因此调度器可以把它们当作可自由填充的独立任务。伪代码思路是：先把 latent 切成 tile 描述符队列，每个描述符携带 tile 坐标、重叠边宽与目标输出偏移；工作 stream 从队列取描述符、解码、把结果写入输出缓冲的对应区域并记录边界带；所有 tile 完成后由一个融合 kernel 在单 stream 上做重叠区加权与全局校正。融合必须等全部 tile 落地，这是一次全局同步点，也是拓扑设计里唯一不能并行的阶段。</p>\n<p>公式上，融合按 <span class=\"formula\">$$\\hat{x}(u)=\\frac{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)\\,D_i(u)}{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)},\\quad w_i(u)=\\exp\\left(-\\frac{\\|u-c_i\\|_2^2}{2\\sigma^2}\\right)$$</span> 执行，$\\mathcal{N}(u)$ 是覆盖像素 $u$ 的 tile 集合。拓扑代价在于：融合 kernel 要读回所有重叠带的解码结果，读回带宽正比于重叠面积乘以覆盖重数；$\\sigma$ 越大，参与融合的 tile 越多，读回与乘加越多。把 $\\sigma$ 压到刚好覆盖重叠带宽，是控制融合代价的主要旋钮。</p>\n<p>具体例子：多 stream 下解码时延随 tile 数近线性下降，前提是 stream 数足够且每 stream 的 tile 激活不超容量。若 stream 数超过单卡可容纳的并发 tile 数，调度退化为串行等待，线性下降失效。因此拓扑参数应写成“并发 tile 数 = min(stream 数, 容量允许的 tile 数)”，并把融合 kernel 放在独立高优先级 stream 上，避免它被后续请求的解码任务挤后。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-27\">二十七 · 量化方案：FP16 解码为主，融合保持高精度</h3>\n<p>本方法的量化基线是 FP16 解码，配合 kernel 融合降低峰值显存。理由直接：VAE 解码器对激活动态范围敏感，重叠区融合是加权求和，若解码输出已被低精度量化，边界带的微小偏差会在加权时被放大成可见色带。因此量化决策应分层——解码器主体走 FP16，融合与色彩校正阶段保持 FP16 甚至更高累加精度，绝不把融合输入降到更窄的格式。这与本卷其他条目讲的 DiT 侧 NVFP4/FP8 是两条线：去噪计算图可以用低精度换吞吐，解码期的空间融合不适合。</p>\n<p>kernel 融合在这里承担双重角色：既减少中间激活的物化次数，也减少精度损失点。把解码器的若干逐元素与归一化操作融进一个 kernel，中间结果留在寄存器与共享内存，避免写回再读的往返；代价是融合 kernel 的寄存器压力上升，占用率下降，单 tile 解码时延可能变长。工程上要按 tile 尺寸标定融合粒度：tile 大时融合收益高，tile 小时寄存器压力更容易成为瓶颈。</p>\n<p>具体例子：同一 tile 若把解码输出先写 FP16 缓冲再由独立融合 kernel 读取，峰值显存多一份整 tile 输出；若把边界带的加权直接融进解码 kernel 的尾部，只保留重叠带而非整 tile 输出，峰值显存与拷贝量同时下降。代价是融合逻辑与解码 kernel 耦合，$\\sigma$ 变化需重新编译或走模板分支，部署时应把 $\\sigma$ 与 tile 边长一起作为编译期常量固定下来。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-28\">二十八 · KV 策略：无缓存的显存预算重分配</h3>\n<p>这套解码路径不需要 KV 缓存——VAE 解码是前馈的逐 tile 计算，没有自回归状态。这一点决定了显存预算的分配方式与其他推理形态完全不同：没有 KV 池要预留，省下的容量应全部给 tile 并发与融合缓冲。部署时要把显存预算显式写成三项：权重常驻、并发 tile 激活、输出缓冲与重叠带。第三项最容易被低估，因为输出缓冲是整图尺寸，重叠带则随 tile 数与重叠宽度增长。</p>\n<p>由于没有 KV，调度参数里也不存在“KV 块数”“前缀复用”这类旋钮，取而代之的是 tile 队列深度与并发上限。队列深度决定流水填充度：深度太浅，stream 在融合同步点前就空了；太深，排队 tile 的描述符与预分配的激活槽位占显存。合理做法是按“并发 tile 数 × 单 tile 激活”预分配槽位，队列只存描述符，不预占激活。</p>\n<p>具体例子：批量图请求到来时，调度器把每张图的 tile 描述符混入同一队列，按到达顺序填充空闲槽位，而不是整图整图地串行。这样单图延迟与批量吞吐能共享同一套并发上限；代价是同一张图的 tile 可能分散在不同时间完成，融合同步点被推迟到该图最后一个 tile 落地，调度器需按图维护完成计数，避免过早触发融合读到未写区域。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-29\">二十九 · 调度参数：tile 尺寸、重叠宽度与 $\\sigma$ 的联合标定</h3>\n<p>调度参数不是独立可调的，它们通过重叠占比耦合。定义重叠占比为重叠带宽与 tile 边长之比，融合额外计算大致正比于该占比乘以覆盖重数。tile 越小，重叠占比越高，融合计算与显存拷贝开销上升，直到抵消显存收益——这正是“tile 过小则算力浪费”的定量形态。标定顺序应是：先按容量定 tile 边长下限，再按接缝可见度定重叠宽度下限，最后按重叠宽度定 $\\sigma$，使权重在重叠带两端平滑衰减到接近零。</p>\n<p>失败模式要在参数层面预防。权重设计不当会在边界产生色带或亮度跳变，且难以用全局校正完全消除；$\\sigma$ 过大使远处 tile 也参与融合，边界被过度平滑，$\\sigma$ 过小则权重在重叠带内不连续，接缝直接暴露。tile 边界处感受野截断导致高频细节不一致，文字与细纹理处出现断裂，这不能靠融合修复，只能靠加大重叠宽度让截断区落在被多 tile 覆盖的带内。</p>\n<p>具体例子：文字区域是感受野截断最敏感的负载。部署时应对含文字的高分辨率请求采用更大的重叠宽度与更小的 $\\sigma$，牺牲一部分融合算力换取边界带内多 tile 覆盖；对纯自然图像则可收紧重叠。把这一判断写成按请求内容分档的调度策略，比全局固定一套参数更稳。收尾的色彩/亮度一致性校正在全部 tile 完成后执行一次，它只能修正全局分布差异，不能替代边界带的权重设计。</p>\n<p>可复现的配置思路归结为一条链：以单 tile 峰值显存选卡与 tile 边长，以容量定并发 tile 数与 stream 数，以接缝可见度定重叠宽度，以重叠宽度定 $\\sigma$ 并固定为编译期常量，解码走 FP16 加 kernel 融合、融合阶段保精度，不预留 KV 而把容量给并发槽位，融合 kernel 置于高优先级 stream 并在每图完成计数达标后触发。任何一环改动都要重跑边界带的高频一致性检查，因为这条链上的参数通过重叠占比相互牵制，单独调一个必然在另一处付出代价。</p>\n\n\n<h3 id=\"alg-vae-tile-decode-sec-30\">三十 · 部署配方的失效边界与代价核算</h3>\n<p>硬件档位由单 tile 峰值显存反推，而非按整图估算：<span class=\"formula\">$$\\text{Mem}_{\\text{peak}}\\approx \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}$$</span> 其中 $\\text{Mem}_{\\text{tile}}$ 随 tile 边长平方增长、$\\text{Mem}_{\\text{model}}$ 为解码器权重常驻部分。工程上先把模型权重与 FP16 激活预算扣掉，剩余显存除以单 tile 激活系数得到 tile 边长上限；2048² 整图解码占数十 GB 的场景，切块后单卡即可容纳。这条配方的失效条件很明确：当 tile 边长小到感受野无法覆盖时，$\\text{Mem}_{\\text{tile}}$ 的下降不再换来质量可接受的输出，此时应换卡而不是继续缩 tile。</p>\n<p>并行拓扑取 tile 级多 stream，tile 数与 stream 数共同决定解码时延的下降斜率。设 tile 数为 $N_t$、单 tile 解码时间为 $t_d$、融合与拷贝开销为 $t_f$，则理想时延近似 <span class=\"formula\">$$\\text{Lat}\\approx \\frac{N_t}{S}\\,t_d+N_t\\,t_f$$</span> 其中 $S$ 为并发 stream 数。$S$ 受 SM 占用与显存带宽约束，超过单卡可承载的并发 tile 数后，时延曲线走平，多 stream 只增加调度开销。量化方案固定为 FP16 解码加 kernel 融合：VAE 解码器对激活动态范围敏感，低位宽量化在重叠区融合时会放大色带，因此量化收益让位于数值稳定，融合 kernel 把归一化、激活与写回合并，减少中间张量驻留。</p>\n<p>该配方无需 KV 缓存，调度参数集中在批大小与 tile 队列深度：批大小按单 tile 显存上限设定，队列深度取 stream 数的整数倍以避免尾部空转。系统代价集中在重叠区：重叠像素占比为 <span class=\"formula\">$$\\rho=\\frac{4\\,o\\,L-4\\,o^2}{L^2}$$</span> 其中 $L$ 为 tile 边长、$o$ 为重叠宽度，$\\rho$ 直接转化为额外解码算力与显存拷贝带宽。tile 过小时 $\\rho$ 升高，融合开销抵消显存收益；权重带宽 $\\sigma$ 过小则接缝处出现亮度跳变，过大则中心区域被邻 tile 稀释、高频细节发软。可复现的配置思路是：先按显存定 tile 边长，再按 $\\rho$ 不超过可接受算力冗余反推重叠宽度，最后以文字与细纹理样本验证边界断裂，若断裂明显则增大 tile 而非调权重。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-31\">三十一 · 部署配方的失效边界：从显存账本到接缝预算</h3>\n<p>这套配方的核心假设是“峰值显存可由单 tile 封顶”，因此选卡与批大小的唯一硬约束是 <span class=\"formula\">$$\\text{Mem}_{\\text{peak}}\\approx \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}$$</span>，其中 <span class=\"formula\">$$\\text{Mem}_{\\text{tile}}$$</span> 随 tile 边长平方增长、<span class=\"formula\">$$\\text{Mem}_{\\text{model}}$$</span> 为 FP16 权重与融合缓冲的固定开销。工程上必须先把这两项量出来再定档位：若单卡余量只够放下一个 tile，那么多 stream 并行就退化为串行，tile 间近线性时延下降的收益归零。批大小同理不能按整图数设定，而应按“同时在飞的 tile 数 × 单 tile 激活”反推，否则高分辨率批量请求会在解码阶段把显存打满，端到端吞吐被这一处瓶颈锁死。</p>\n<p>并行拓扑选 tile 级多 stream，代价是重叠区带来的额外计算与显存拷贝。重叠占比可写成 <span class=\"formula\">$$\\rho=\\frac{A_{\\text{tile}}-A_{\\text{unique}}}{A_{\\text{tile}}}$$</span>，tile 越小 <span class=\"formula\">$$\\rho$$</span> 越高，融合算力与写回带宽同步上升，直到抵消显存收益——这就是 tile 尺寸的下界，而不是上界。融合本身按 <span class=\"formula\">$$\\hat{x}(u)=\\frac{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)\\,D_i(u)}{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)}$$</span> 做加权，带宽 <span class=\"formula\">$$\\sigma$$</span> 过窄则权重在边界陡降，色带与亮度跳变出现且全局校正难以完全消除；过宽则单像素被多个 tile 重复贡献，融合开销上升。</p>\n<p>量化方案上，FP16 解码配合 kernel 融合是这条路径的默认档：更低位宽虽能再压 <span class=\"formula\">$$\\text{Mem}_{\\text{tile}}$$</span>，但 VAE 解码器对激活动态范围敏感，低位量化在重叠区放大接缝，属于用画质换显存的负收益交换。KV 策略在此不适用——解码期无自回归缓存，显存预算应全部让给 tile 激活与输出缓冲。调度参数只需控制两件事：单卡并发 tile 数不超过显存账本允许值，以及全部 tile 完成后强制一次色彩/亮度一致性校正。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>工程判断</th></tr></thead><tbody><tr><td>tile 过小、重叠占比高</td><td>融合算力与拷贝带宽上升，显存收益被抵消</td><td>以 <span class=\"formula\">$$\\rho$$</span> 设 tile 下界</td></tr><tr><td>权重带宽 <span class=\"formula\">$$\\sigma$$</span> 失配</td><td>边界色带、亮度跳变，需返工校正</td><td>按重叠像素数标定 <span class=\"formula\">$$\\sigma$$</span></td></tr><tr><td>tile 边界感受野截断</td><td>文字与细纹理断裂，高频不一致</td><td>重叠像素须覆盖感受野半径</td></tr></tbody></table>\n<p>最容易被忽略的是感受野截断：重叠像素若小于解码器有效感受野半径，边界处的高频细节无法由邻 tile 补齐，融合只能平滑接缝而不能恢复信息，文字与细纹理处出现断裂。这一约束与 tile 尺寸上界直接冲突——tile 越大显存越紧张，tile 越小重叠占比越高，可行区间由“感受野覆盖”与“显存账本”两条线夹出，超出该区间的配置在 2048² 这类高分辨率输入上必然以画质或吞吐之一为代价。</p>\n<h3 id=\"alg-vae-tile-decode-sec-32\">三十二 · 峰值显存的真实构成与“先崩点”</h3>\n<p>把整图解码拆成 tile 之后，端到端显存并不等于“单 tile 激活 + 权重”这么简单。工程上真正要盯的是四块：单 tile 的激活峰值 $\\text{Mem}_{\\text{tile}}$、模型权重与常量 $\\text{Mem}_{\\text{model}}$、输出缓冲 $\\text{Mem}_{\\text{out}}$（整图尺寸，FP16 下随分辨率平方增长），以及多 stream 并行时被同时驻留的 tile 激活集合。前文给出的近似式只描述了前两项：</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{peak}}\\approx \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}$$</div>\n<p>但在 $S$ 条 stream 并发时，实际峰值更接近 $\\text{Mem}_{\\text{model}}+\\text{Mem}_{\\text{out}}+S\\cdot\\text{Mem}_{\\text{tile}}$。这就是规模上去以后第一个崩的地方：不是单 tile 太大，而是并发度 $S$ 把激活峰值乘了上去。2048² 整图解码可占数十 GB，切块后单 tile 激活被压到可控量级，但只要把 $S$ 从 2 提到 8，激活项就回到同一数量级，显存收益被并发吃掉。判断准则很直接：先算出 $\\text{Mem}_{\\text{out}}$ 与 $\\text{Mem}_{\\text{model}}$ 的固定开销，剩余预算除以 $\\text{Mem}_{\\text{tile}}$ 得到可承受的并发上限，再决定 tile 尺寸与 stream 数。tile 调小能抬高并发上限，但重叠占比上升，算力浪费随之而来——这是显存与算力之间的直接兑换，不存在两边都省的配置。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-33\">三十三 · 带宽：融合写回比解码本身更贵</h3>\n<p>分块解码的带宽账常被低估。每个 tile 解码完成后要写回输出缓冲，重叠区的像素被多个 tile 各写一次，融合阶段还要再读一次做加权。设 tile 边长 $T$、重叠宽度 $o$，重叠像素占比约为 $1-(1-o/T)^2$，当 $T=256$、$o=32$ 时约 23% 的像素被重复写。融合公式本身是逐像素的加权和：</p>\n<div class=\"formula\">$$\\hat{x}(u)=\\frac{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)\\,D_i(u)}{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)},\\quad w_i(u)=\\exp\\left(-\\frac{\\|u-c_i\\|_2^2}{2\\sigma^2}\\right)$$</div>\n<p>它要求把覆盖同一像素的所有 tile 结果同时放在可读位置，于是融合要么在片上做（需要 tile 结果驻留），要么走 HBM 往返（写一次、读多次）。后者在 2048² 量级上会把解码阶段的带宽压力放大 2–3 倍：解码是计算密集的卷积/上采样，融合是纯带宽操作，两者在时间上串行时，端到端吞吐由融合段决定。工程做法是把融合权重预先算成常量图（只与 tile 几何有关，与内容无关），并把加权和融进解码 kernel 的尾部 epilogue，使 tile 结果不落 HBM 就直接累加到输出缓冲，代价是输出缓冲需要以 FP32 累加、最后再转 FP16，输出缓冲的字节数翻倍——这又回到第一节的显存预算里。带宽与显存在这里是同一个约束的两面。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-34\">三十四 · 通信：tile 级并行的拓扑选择</h3>\n<p>单卡内 tile 并行用多 stream 即可，不涉及跨设备通信；一旦单卡放不下整图输出缓冲或并发度需求超过单卡上限，就必须把 tile 分到多卡。此时通信量由 tile 边界决定：每个 tile 需要它感受野范围内的 latent 上下文，边界重叠区就是必须交换的 halo 区域。halo 的数据量约为 $4\\cdot T\\cdot o\\cdot C_{\\text{latent}}$ 字节每 tile，与 tile 面积成正比而与整图面积无关，这是分块并行的通信优势——总通信量随 tile 数线性增长，而不是随分辨率平方增长。但融合阶段是全局操作：覆盖同一像素的 tile 若落在不同设备上，加权和需要跨设备归约，这一步的通信量与重叠像素数成正比，且必须在所有 tile 解码完成后同步。NVLink 5 域内做这一步的代价可接受，跨节点则会把尾延迟拉长。工程判断：把重叠区尽量限制在单设备内（按设备边界对齐 tile 网格），让跨设备只交换 halo 而不交换融合中间结果，能把集合通信从“每像素多次”降到“每 tile 一次”。NIXL 这类传输层在这里的价值是让 halo 交换与解码计算重叠，而不是降低通信总量。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-35\">三十五 · 功耗与热：并发度是隐形的功耗旋钮</h3>\n<p>分块解码把一个大 kernel 拆成许多小 kernel，单 tile 的计算强度下降，SM 占用率与 tensor core 利用率都不如整图解码饱满。这意味着在相同吞吐下，分块方案的每瓦性能更差：kernel 启动开销、tile 边界处的流水线气泡、融合段的纯带宽操作都不产生有效浮点运算。FP16 解码配合 kernel 融合能缓解一部分——融合把多个小算子合成一个，减少启动与中间写回，但无法改变“小 tile 计算强度低”的本质。功耗上的直接后果是：为了达到与整图解码相同的吞吐，需要更高的并发度，而并发度又推高显存与带宽需求，形成一条“功耗—并发—显存”的耦合链。在 GB200/GB300 NVL72 这类整机柜部署里，这条链的末端是机柜功率预算：解码阶段的功耗峰值若与预填/去噪阶段错峰，可以用时间上的调度把峰值削平；若同时发生，则要么降并发、要么拉长尾延迟。规模上去后第二个崩的点往往不是算力不够，而是功率墙先到。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-36\">三十六 · 尾延迟：融合同步点是长尾的来源</h3>\n<p>tile 间可并行，多 stream 下解码时延随 tile 数近线性下降——这是平均时延的故事。尾延迟的故事不同：全部 tile 完成后要做一次色彩/亮度一致性校正，这是一个全局同步点，任何一条 stream 上的慢 tile 都会把整图完成时间往后拖。慢 tile 的来源有三类：边界 tile 因感受野截断需要额外填充、重叠区权重计算带来的额外访存、以及多 stream 争抢带宽时的调度抖动。设单 tile 解码时延为 $t$、并发度为 $S$、tile 数为 $N$，理想完成时间为 $\\lceil N/S\\rceil\\cdot t$，而实际尾延迟取决于最慢那条 stream 的累计时间。工程上把 tile 按计算量排序后做最长优先调度（LPT），能把尾延迟从“最慢 tile 决定”压到“负载均衡决定”；把全局校正改成流式校正（每个 tile 写回时即按邻域统计量做局部校正，最后只做一次极轻的全局偏移）可以消除那个硬同步点，代价是校正精度略降、接缝风险上升。SLO 以解码时延为主时，尾延迟而非平均时延才是容量规划的输入。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-37\">三十七 · 规模上去以后，崩的顺序</h3>\n<p>把上述几条按“先崩”排序，可以得到一个工程判断序列。第一步崩的是显存：并发度乘以单 tile 激活，加上整图输出缓冲，最先撞上单卡容量上限，表现为必须降 $S$ 或降分辨率。第二步崩的是带宽：融合段的重复读写让解码从计算受限转为带宽受限，吞吐不再随并发线性增长。第三步崩的是尾延迟：全局校正同步点与慢 tile 叠加，P99 时延脱离平均值独立上升，SLO 先于吞吐告警。第四步才是功耗与通信：前者在整机柜部署里表现为功率封顶，后者在跨节点 halo 交换与融合归约时表现为集合通信等待。这个顺序的含义是：调优应从显存预算反推 tile 尺寸与并发度，再用融合 kernel 把带宽压力压回计算段，最后用调度与流式校正削尾——而不是先堆并发再看哪里报错。tile 过小使重叠区占比升高、融合计算与显存拷贝开销抵消显存收益，这条失败模式正是第一步与第二步耦合的产物：显存省下来的部分，被带宽和算力浪费吃回去。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-38\">三十八 · 规模上去以后：先崩在显存墙，再崩在重叠比与尾延迟</h3>\n<p>这套方案的吞吐天花板不在算力，而在“单 tile 激活峰值 × 并发 tile 数”与输出缓冲的叠加。峰值显存可写成 <span class=\"formula\">$$\\text{Mem}_{\\text{peak}}\\approx N_{\\text{inflight}}\\cdot \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}+\\text{Mem}_{\\text{out}}$$</span>，其中 <span class=\"formula\">$N_{\\text{inflight}}$</span> 是同时在解码器里的 tile 数。整图解码时 <span class=\"formula\">$\\text{Mem}_{\\text{tile}}$</span> 一项就是整幅激活，2048² 单图可占数十 GB；分块后该项被压到单 tile 量级，但 <span class=\"formula\">$\\text{Mem}_{\\text{out}}$</span>（全分辨率输出缓冲）与模型权重不随切块缩小。于是规模上去的第一个崩点很明确：当你为提吞吐把 <span class=\"formula\">$N_{\\text{inflight}}$</span> 从 1 拉到 4、8，显存按并发线性回升，很快重新撞上整图解码的那堵墙——切块买到的是“能跑”，不是“能无限并发”。工程判断是：并发度必须由单 tile 峰值显存反推，而不是由 SM 占用率反推；一旦 <span class=\"formula\">$N_{\\text{inflight}}$</span> 触顶，继续加 stream 只增加排队，不增加吞吐。</p>\n<p>第二个崩点是重叠比。设 tile 边长 <span class=\"formula\">$T$</span>、重叠带宽 <span class=\"formula\">$o$</span>，有效算力利用率约为 <span class=\"formula\">$$\\eta\\approx\\left(\\frac{T}{T+o}\\right)^{2}$$</span>。重叠区要跑两遍解码、再做加权融合与写回，<span class=\"formula\">$o$</span> 取 <span class=\"formula\">$T$</span> 的 1/8 时 <span class=\"formula\">$\\eta$</span> 已掉到 0.79 量级，取 1/4 则只剩 0.64。tile 越小显存越省，但重叠占比升高，融合计算与显存拷贝开销抵消显存收益，这就是“tile 过小反而更慢”的定量来源。更麻烦的是带宽：每个 tile 的激活要写回输出缓冲、重叠区要被多个 tile 读写，融合阶段是典型的读—改—写模式，HBM 流量随重叠像素数增长，而这一步没有矩阵乘的算术强度来掩护，纯带宽受限。因此在显存够用的前提下，把 tile 调大、把重叠压到刚好覆盖感受野，通常比堆并发更划算。</p>\n<p>第三个崩点是尾延迟与一致性校正的串行段。tile 间可并行，多 stream 下解码时延随 tile 数近线性下降，但这条曲线有下限：全部 tile 完成后要做一次色彩/亮度一致性校正，这是全局操作，必须等最慢的 tile 落地。于是端到端时延呈 <span class=\"formula\">$$L\\approx \\max_{i} L_i + L_{\\text{corr}}$$</span> 的形状，<span class=\"formula\">$L_{\\text{corr}}$</span> 不随并行度缩小，成为高并发下的固定尾巴；批量图请求里若混入不同分辨率，最慢那张的 tile 数决定整批的尾延迟。失效条件也集中在这里：权重设计不当会在 tile 边界留下色带或亮度跳变，全局校正只能压平分布差异，压不掉接缝本身；tile 边界感受野截断使高频细节不一致，文字与细纹理处出现断裂，这类错误在缩略图里看不见、在全分辨率验收时才暴露。功耗侧则是另一重代价：融合与拷贝把时间花在数据搬运上，SM 利用率低而 HBM 与 L2 长期高负载，单位图像的能耗比整图解码更差——省的是显存，不是焦耳。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的位置</th><th>系统代价</th><th>工程对策</th></tr></thead><tbody><tr><td>并发 tile 数上调</td><td>激活峰值重回数十 GB 量级</td><td>显存、OOM 重试</td><td>按单 tile 峰值反推并发上限</td></tr><tr><td>tile 尺寸下调</td><td>重叠比升高、融合带宽受限</td><td>吞吐、HBM 流量</td><td>tile 取到感受野下限，重叠只覆盖边界</td></tr><tr><td>批量图混分辨率</td><td>最慢 tile 决定尾延迟</td><td>尾延迟、SLO 违约</td><td>按 tile 数分桶调度，校正段异步化</td></tr><tr><td>高分辨率视频帧</td><td>帧间一致性校正串行化</td><td>时延、功耗</td><td>帧内并行、帧间流水，FP16 解码配 kernel 融合</td></tr></tbody></table>\n<p>把三者叠起来看，规模上限由两个约束共同封顶：单 tile 感受野决定 tile 不能太小，融合权重带宽 <span class=\"formula\">$\\sigma$</span> 决定重叠不能太窄，二者一起把 <span class=\"formula\">$\\eta$</span> 锁在一个上界之下；而 <span class=\"formula\">$N_{\\text{inflight}}$</span> 又被显存锁死。真正先崩的通常不是算力，而是“输出缓冲 + 并发激活”的显存账，其次才是重叠带来的带宽账，最后是校正段的尾延迟账。判断一个部署是否已越过边界，看三个信号即可：并发上调后吞吐不再增长、融合阶段 HBM 利用率逼近饱和、尾延迟分位数与 tile 数同步抬升——任一出现，就该回到 tile 尺寸与重叠带宽上做取舍，而不是继续加卡。</p>\n<h3 id=\"alg-vae-tile-decode-sec-39\">三十九 · 精度失败的三条链路：融合权重、感受野截断、全局校正失效</h3>\n<p>分块解码的精度问题不是单一来源，而是三条独立链路叠加的结果，诊断时必须先分离链路再定位。第一条链路在融合权重本身：<span class=\"formula\">$$w_i(u)=\\exp\\left(-\\frac{\\|u-c_i\\|_2^2}{2\\sigma^2}\\right)$$</span> 中 $\\sigma$ 与重叠宽度的比值决定了权重曲线的陡峭程度。当 $\\sigma$ 远小于重叠宽度时，权重在 tile 中心附近迅速饱和、在边界附近迅速衰减，融合结果对 tile 间微小的分布差异变得敏感，表现为边界处的亮度台阶；当 $\\sigma$ 远大于重叠宽度时，权重趋于平坦，边界像素被多个 tile 近似等权平均，高频成分被平滑掉，表现为细纹理发虚。工程上应把 $\\sigma$ 绑定到重叠像素数而非固定常数，使权重曲线在重叠区内单调过渡，避免出现双峰。</p>\n<p>第二条链路是感受野截断。VAE 解码器的每一层卷积都在扩大有效感受野，tile 边界处的输出像素实际依赖 tile 外部的 latent 值，切块后这部分上下文被硬性置零或复制填充，导致边界像素的解码结果与整图解码不一致。这种不一致不是随机噪声，而是系统性的高频偏差：文字笔画、织物纹理、细网格在边界处出现断裂或重影。诊断方法是构造一个已知解析解的合成 latent（例如规则条纹或棋盘格），对比分块解码与整图解码在边界带内的 PSNR 梯度——若边界带 PSNR 显著低于内部区域，即为感受野截断的确证，而非权重问题。</p>\n<p>第三条链路是收尾的色彩/亮度一致性校正。该校正假设 tile 间差异是全局仿射可修正的，但当某个 tile 因感受野截断产生了结构性偏差时，全局校正只能拉平均值，无法消除边界处的局部跳变。因此校正步骤本身会成为失败模式的掩蔽层：它让整体指标看起来正常，却把接缝留在高频区域。监控上应把校正前后的边界梯度分别记录，若校正后边界梯度仍高于内部梯度基线，说明问题不在色彩分布而在结构。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-40\">四十 · 显存失败：峰值不在单 tile，而在缓冲与融合中间态</h3>\n<p>公式 <span class=\"formula\">$$\\text{Mem}_{\\text{peak}}\\approx \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}$$</span> 描述的是理想情况，实际 OOM 往往发生在公式之外。三个隐性占用必须纳入监控：其一，输出缓冲。全部 tile 的结果要写回一张全分辨率输出张量，2048² 的 FP16 输出本身即数 GB 量级，若框架在写回时做了隐式类型提升或布局转换，会额外产生一份临时副本。其二，融合中间态。按 $\\hat{x}(u)$ 逐像素加权需要同时持有覆盖该像素的所有 tile 结果及其权重，若实现为“先全部解码再统一融合”，则所有 tile 激活同时驻留，峰值退化为全图解码。其三，多 stream 并发。tile 级并行通过多 stream 提升时延，但并发 tile 数乘以单 tile 激活即为实际峰值，调度器若按 stream 数无节制放大并发，OOM 会在负载上升时突然出现而非渐进出现。</p>\n<p>诊断 OOM 的第一步是区分“瞬时峰值”与“驻留峰值”。用显存采样按固定间隔记录分配量，若曲线呈锯齿状且峰值随并发 tile 数线性上升，问题在并发调度；若曲线单调爬升不回落，问题在 tile 激活未及时释放或输出缓冲重复分配。工程判断上，应把并发 tile 数作为显存预算的一等约束显式配置，而不是交给框架的默认启发式；同时确保每个 tile 解码完成后立即释放其激活，融合只保留重叠带内的切片而非整块 tile 结果。当单卡无法容纳“输出缓冲 + 最大并发 tile 激活 + 模型权重”三者之和时，正确做法是降低并发而非缩小 tile——缩小 tile 会同时抬高重叠占比与融合开销，属于用算力换显存的下策。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-41\">四十一 · 批抖动与路由不均：tile 粒度打散了批的语义</h3>\n<p>分块解码把一次请求拆成多个 tile 任务，批处理的基本单位从“请求”变成了“tile”，这直接改变了批调度的行为。批抖动表现为同一批内 tile 任务的解码耗时方差大：位于图像边缘的 tile 与位于中心的 tile 在内容复杂度上不同，含高频纹理的 tile 解码更慢，而调度器若按固定批大小组批，快 tile 要等待慢 tile，形成批内拖尾。更隐蔽的问题是路由不均：多 stream 或多副本部署时，tile 任务按到达顺序而非按负载分配，导致某些 stream 堆积、某些空闲，整体时延由最忙的 stream 决定。</p>\n<p>诊断批抖动需要按 tile 维度而非请求维度统计耗时分布，观察 P50 与 P99 的比值；若比值随批大小增大而恶化，说明组批策略未考虑 tile 异构性。缓解手段是按 tile 的内容复杂度或历史耗时做分桶，把同量级 tile 组批，代价是增加了调度器的元数据开销与组批延迟。路由不均的诊断则依赖每个 stream 的在途任务数与完成速率，若在途任务数的方差持续偏高，应改为按 stream 当前负载做拉取式分发而非推送式。这里的系统代价是明确的：tile 级并行让解码时延随 tile 数近线性下降，但这一收益只有在路由均衡时才成立；一旦某个 stream 成为瓶颈，时延曲线会从线性转为平台，继续增加 stream 数不再有效。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-42\">四十二 · 尾延迟尖刺：重叠带放大与融合串行点</h3>\n<p>尾延迟尖刺在分块解码中有两个特有来源。第一个是重叠带的计算放大：重叠区像素被多个 tile 重复解码，重叠占比越高，单位输出像素的实际计算量越大。当请求分辨率上升、tile 尺寸不变时，tile 数量增加但重叠占比不变；而当 tile 尺寸被迫缩小时（例如为适配显存而降并发失败后的回退），重叠占比上升，尾部的慢 tile 数量随之增加，P99 时延被结构性抬高。第二个来源是融合与全局校正的串行点：所有 tile 完成后才能做色彩/亮度一致性校正，这一步是全局同步屏障，任何一个慢 tile 都会把整个请求的完成时间拖到它的结束时刻。因此尾延迟不由平均 tile 耗时决定，而由最慢 tile 加上校正耗时决定。</p>\n<p>监控上应把“最后一块 tile 完成时刻减去首块 tile 开始时刻”作为独立的时延指标，与总时延分开记录；两者之差即为并行调度未能掩盖的拖尾。缓解手段包括：对慢 tile 做预测性拆分（把大 tile 再切成子 tile 以增加并行度），或在融合阶段采用增量式写回使部分结果提前落盘，把全局校正从同步屏障改为流式修正。代价是增量融合需要维护跨 tile 的权重累积状态，显存与实现复杂度上升；而预测性拆分会在尾部引入额外的调度开销，只在拖尾显著时才值得启用。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-43\">四十三 · 监控面与回滚判据</h3>\n<p>针对上述失败模式，监控面应至少覆盖四组信号，且每组都绑定到可执行的判据而非仅做展示。精度组：边界带与内部区域的梯度基线之比、校正前后边界梯度差、合成 latent 的边界 PSNR；显存组：按并发 tile 数的峰值采样、输出缓冲分配次数、tile 激活释放延迟；调度组：tile 耗时 P50/P99 比、每 stream 在途任务数方差、组批等待时间；时延组：首末 tile 时间差、校正阶段耗时占比。每组信号都应设定阈值并关联到具体动作，例如边界梯度比超阈值时冻结当前 $\\sigma$ 配置并回退到上一组权重参数。</p>\n<p>回滚判据的设计原则是“按失败链路回滚，而非整体回退”。精度类失败（色带、纹理断裂）应回滚融合权重与重叠宽度配置，因为这两者是精度链路的直接输入；显存类失败应回滚并发 tile 数与输出缓冲策略，而非回退到整图解码——整图解码在 2048² 下本就不可行；调度类失败应回滚组批与分发策略；尾延迟类失败应回滚 tile 尺寸与拆分策略。回滚必须保留版本化的配置快照，使每次变更可归因到单一参数，避免多参数同时调整导致失败链路无法分离。工程判断上，分块解码的稳定性不取决于单点最优参数，而取决于参数变更的可回退性与监控信号对失败链路的可分辨性；当监控只能看到“整体变慢”而无法区分是路由不均还是重叠放大时，任何回滚都是盲目的。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-44\">四十四 · 融合权重失配、感受野截断与 tile 粒度反噬：三类失效的定位与回滚</h3>\n<p>这套方案最脆弱的地方不在解码 kernel，而在融合公式本身。<div class=\"formula\">$$\\hat{x}(u)=\\frac{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)\\,D_i(u)}{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)},\\quad w_i(u)=\\exp\\left(-\\frac{\\|u-c_i\\|_2^2}{2\\sigma^2}\\right)$$</div>当 $\\sigma$ 与重叠宽度不匹配时，权重在重叠区中心附近过平、在边缘处骤降，相邻 tile 的贡献比例出现阶跃，输出上表现为沿 tile 边界的色带或亮度跳变。这类误差是空间低频的，收尾的色彩/亮度一致性校正只能压均值、压不掉梯度，因此监控必须落在融合前的中间量上：按 tile 记录重叠区两侧 $D_i(u)$ 的逐通道均值差与梯度差，超过阈值即判定权重带宽失配，回滚动作是把 $\\sigma$ 调至重叠宽度的固定比例并重跑受影响 tile，而不是重跑全图。</p>\n<p>第二类失效来自感受野截断。VAE 解码器的有效感受野大于 tile 尺寸时，边界像素缺少外侧上下文，高频细节在文字、细纹理处断裂，且断裂位置随 tile 网格固定，肉眼极易识别。诊断手段是把同一 latent 用整图解码（小分辨率样本）与分块解码做逐像素差，统计边界带的能量占比；若边界带误差能量显著高于内部，说明 tile 尺寸已逼近感受野下限。此时的工程判断不是继续缩小 tile 省显存，而是扩大重叠像素或改用更大的 tile 配合多 stream 并行——显存与保真度在这里是直接对冲的。</p>\n<p>第三类失效是 tile 粒度反噬与批抖动。tile 过小使重叠区占比升高，融合计算与显存拷贝开销抵消显存收益，峰值显存虽降但端到端时延不再随 tile 数线性下降；同时批大小按单 tile 显存上限设定，一旦请求分辨率变化导致 tile 数跳变，批内 tile 数不均会引起 stream 间负载倾斜，尾延迟出现尖刺。监控应同时盯三个量：单 tile 激活峰值（对照 <div class=\"formula\">$$\\text{Mem}_{\\text{peak}}\\approx \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}$$</div>判断是否触及 OOM 边界）、重叠像素占比、以及各 stream 的 tile 完成时间方差。方差抬升即触发回滚：固定 tile 尺寸与重叠比例、按分辨率分桶而非动态切分，把路由不均收敛到可预测的桶内。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>根因</th><th>监控量</th><th>回滚动作</th></tr></thead><tbody><tr><td>边界色带</td><td>$\\sigma$ 与重叠宽度失配</td><td>重叠区逐通道均值差</td><td>重设 $\\sigma$，重跑受影响 tile</td></tr><tr><td>细节断裂</td><td>感受野截断</td><td>边界带误差能量占比</td><td>扩大重叠或增大 tile</td></tr><tr><td>尾延迟尖刺</td><td>tile 数跳变、stream 不均</td><td>tile 完成时间方差</td><td>固定切分、按分辨率分桶</td></tr></tbody></table>\n<h3 id=\"alg-vae-tile-decode-sec-45\">四十五 · 对照轴：切分发生在计算图的哪个位置</h3>\n<p>把 VAE 分块并行解码放进同族算法里比较，第一件事不是比显存数字，而是定位“切分点”落在计算图的哪一段。本方法只在 VAE 解码期做空间切块，去噪计算图原封不动；阶段级扩散服务流水切的是管线阶段（预填/去噪/解码分置于不同资源池）；patch 级调度在去噪前就把 latent 按空间补丁拆开，让每个补丁独立走完整个去噪链。三者的切分点分别位于解码器内部、阶段边界、去噪入口，这决定了它们能省什么、必须付什么。</p>\n<p>切在解码器内部，省的是解码激活：峰值被约束在单 tile 内，满足 <span class=\"formula\">$$\\text{Mem}_{\\text{peak}}\\approx \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}$$</span> 这一关系，模型权重是固定项，可压缩的只有 tile 激活项。切在阶段边界，省的是资源错配，代价是阶段间 latent 搬运与流水气泡。切在去噪入口，省的是整条链的激活，但每个补丁都要独立承担完整的去噪步数与条件注入，算力复用率下降。因此选型的第一判据是：瓶颈究竟在解码激活，还是在阶段间等待，还是在去噪本身的算力密度。</p>\n<p>一个具体例子：2048² 图像在整图解码路径下单张解码激活可达数十 GB，端到端吞吐被显存卡死；此时把切分点放在解码器内部，峰值降到单 tile 量级，单卡即可完成，而去噪侧的超分条件、CFG 批合并逻辑完全不用改写。反过来，若瓶颈是去噪阶段与解码阶段抢同一张卡的 SM，则切分点应上移到阶段边界，让解码走独立资源池。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-46\">四十六 · 决策表：四类候选与硬性适用条件</h3>\n<p>下表把同族候选按“切分点 / 省什么 / 付什么 / 硬性适用条件”四列对齐，便于在工程评审时直接勾选。表中不写性能倍数，只写机制层面的取舍，因为倍数依赖 tile 尺寸、重叠比例与卡型，属于部署配方范畴。</p>\n<table class=\"mini\"><thead><tr><th>候选</th><th>切分点</th><th>主要收益</th><th>主要代价</th><th>硬性适用条件</th></tr></thead><tbody>\n<tr><td>VAE 分块并行解码（本方法）</td><td>解码器内部，空间 tile + 重叠</td><td>解码激活峰值降到单 tile，2048² 单卡可解</td><td>重叠区额外计算、接缝与色带风险、边界感受野截断</td><td>瓶颈确在解码激活；tile 尺寸不小于感受野覆盖需求；有可用的融合权重与收尾校正</td></tr>\n<tr><td>阶段级扩散服务流水</td><td>管线阶段边界</td><td>预填/去噪/解码资源解耦，各自按 SLO 扩容</td><td>阶段间 latent 传输、流水气泡、调度复杂度</td><td>多副本、有独立资源池；请求到达率足以填满流水</td></tr>\n<tr><td>patch 级调度（去噪前切分）</td><td>去噪入口</td><td>整链激活下降，补丁可独立调度</td><td>每补丁重复条件注入与步数，算力复用差；补丁间一致性需额外处理</td><td>去噪本身是激活瓶颈；补丁边界与条件图兼容</td></tr>\n<tr><td>整图解码（基线）</td><td>不切分</td><td>无接缝、无重叠浪费、实现最简</td><td>激活随分辨率平方增长，高分辨率下不可行</td><td>分辨率与批大小使激活落在显存预算内</td></tr>\n</tbody></table>\n<p>读表时注意两条硬约束。其一，本方法与 patch 级调度不叠加使用：前者假设去噪图完整，后者已经把去噪切开，叠加会让补丁边界与 tile 边界错位，融合权重失去意义。其二，本方法与阶段级流水可叠加，但叠加后解码阶段的容量规划要按“单 tile 峰值 × 并发 tile 数”估算，而不是按整图峰值估算，否则会过度预留显存。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-47\">四十七 · 融合公式的选型含义：权重带宽决定 tile 尺寸下限</h3>\n<p>融合式 <span class=\"formula\">$$\\hat{x}(u)=\\frac{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)\\,D_i(u)}{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)},\\quad w_i(u)=\\exp\\left(-\\frac{\\|u-c_i\\|_2^2}{2\\sigma^2}\\right)$$</span> 里，$\\sigma$ 不是一个可以随手调的装饰参数，它把 tile 尺寸与接缝质量绑在一起。$\\sigma$ 相对重叠宽度过小，权重在重叠区迅速衰减，融合退化为硬拼接，边界出现亮度跳变；$\\sigma$ 过大，远端 tile 的权重不可忽略，等于把截断感受野的错误细节也平均进来，高频处发糊。工程上应让 $\\sigma$ 与重叠宽度同量级，使重叠区内权重过渡覆盖整个过渡带。</p>\n<p>这条约束反过来给出 tile 尺寸下限：重叠宽度必须容纳感受野截断造成的误差带，tile 越小，重叠占比越高，融合计算与显存拷贝开销上升，抵消显存收益。伪代码层面的判断很直接：设 tile 边长 $T$、重叠 $O$，有效计算量为 $\\left(\\frac{T}{T-O}\\right)^2$ 倍，当 $O/T$ 超过某个比例时，多 stream 并行带来的时延下降被额外计算吃掉。因此选型时应先由感受野定 $O$，再由显存预算定 $T$，最后检查 $O/T$ 是否落在可接受区间；若不在，说明该分辨率不适合本方法，应转向阶段级流水或降低分辨率。</p>\n<p>系统代价上，融合阶段本身是带宽操作：每个重叠像素被读写多次，输出缓冲的写回与 tile 激活的释放交替进行。FP16 解码配合 kernel 融合能把这部分开销压到可接受范围，但融合 kernel 的访存模式若不佳，重叠区会成为新的带宽热点。一个具体判断：文字与细纹理密集的图像，边界断裂最容易被用户察觉，此时应优先增大重叠而不是减小 tile。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-48\">四十八 · 时延模型：tile 并行度与 SLO 的匹配</h3>\n<p>本方法的时延结构是“单 tile 解码时延 × 串行轮数 + 融合时延”。多 stream 下 tile 间可并行，解码时延随 tile 数近线性下降，但这条线性只在 stream 数与 SM 占用匹配时成立：stream 过多导致单 tile 的 kernel 抢占，反而拉长尾延迟；stream 过少则显存峰值虽低但时延不降。容量规划时应把并发 tile 数设为“单 tile 峰值显存 × 并发数 ≤ 卡上可用显存”的最大整数，再核对这个并发数能否填满 SM。</p>\n<p>与阶段级流水对照：流水的时延由最慢阶段决定，且存在排队与气泡，适合吞吐优先、时延 SLO 宽松的服务；本方法的时延由 tile 轮数与融合决定，适合解码时延为主 SLO 的场景。与 patch 级调度对照：后者时延随补丁数增长且每补丁都要跑完整去噪，单请求时延通常更长，但整链激活更低，适合显存极紧而时延可放宽的批处理。</p>\n<p>具体例子：一批 2048² 图像请求，SLO 以单图解码时延为主。若卡上显存只够一个 tile 峰值加模型权重，则并发 tile 数为 1，时延退化为串行逐 tile，此时应改用阶段级流水把解码放到独立卡上，而不是硬压 tile 尺寸——压小 tile 会让重叠占比升高，融合开销抵消并行收益。这个判断不需要实测数字，只需比较“串行 tile 轮数 × 单 tile 时延”与“跨卡传输 + 流水气泡”的量级。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-49\">四十九 · 质量风险的分工：谁负责接缝，谁负责一致性</h3>\n<p>四类候选在质量风险上的分工不同，选型时必须明确“谁兜底”。本方法的接缝风险来自重叠区权重设计与边界感受野截断，兜底手段是融合权重加全部 tile 完成后的色彩/亮度一致性校正；但校正只能消除 tile 间分布差异，无法修复权重设计不当造成的色带，也无法修复文字与细纹理处的断裂。也就是说，本方法的质量上限由 tile 尺寸与重叠宽度在选型阶段就决定，运行期校正只是收尾。</p>\n<p>阶段级流水不引入空间接缝，但阶段间 latent 量化或传输误差会体现为整体画质漂移，兜底靠端到端精度对齐。patch 级调度的接缝风险最高：补丁边界同时切断了去噪链与解码链，边界处不仅感受野截断，条件注入也可能不一致，需要跨补丁的一致性机制，代价高于本方法的融合。整图解码无接缝，但高分辨率下根本跑不起来，质量优势无从谈起。</p>\n<p>工程判断可以写成一条规则：若图像内容以大面积平滑区域为主，本方法的接缝风险低，选它；若内容以文字、细纹理、锐利边缘为主，且 SLO 允许更高时延，应优先考虑不切分解码或阶段级流水；若必须在显存受限下处理这类内容，则把重叠宽度按最坏感受野设定，并接受融合计算带来的吞吐下降。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-50\">五十 · 组合与禁用：与量化、缓存的相邻关系</h3>\n<p>本方法与解码期量化正交：FP16 解码是部署配方里的默认档位，若进一步降到更低精度，tile 边界处的量化误差会与融合权重叠加，色带风险上升，因此量化选型应单独评估，不与 tile 尺寸联动调整。与特征缓存、块级跳步这类去噪期优化也不冲突，因为它们作用在去噪图内部，本方法不动去噪图；但若缓存机制依赖整图 latent 的空间连续性，切分点仍应保持在解码器内部，避免缓存命中率因补丁化而下降。</p>\n<p>禁用条件要写清楚：当单 tile 峰值显存加模型权重已接近卡上可用显存时，本方法失去意义，因为并发 tile 数为 1，时延不降反升；当重叠占比高到融合计算超过解码本身时，本方法的经济性消失；当输出对边界连续性有硬性要求且无法用校正兜底时，应改用不切分路径。反过来，本方法的最佳适用面是高分辨率图像与视频帧解码的显存受限场景，且请求形态为高分辨率单图或批量图、批大小按单 tile 显存上限设定。</p>\n<p>最后落在一条可执行的选型动作上：先测整图解码的激活峰值，若它超过卡上可用显存的某个比例而端到端吞吐被卡住，则把切分点定在解码器内部；再由感受野定重叠宽度、由显存预算定 tile 边长，检查重叠占比是否可接受；若不可接受，把切分点上移到阶段边界，用独立资源池换掉 tile 并行。这条路径不依赖具体卡型数字，只依赖峰值显存、感受野与 SLO 三个可测的量。</p>\n\n<h3 id=\"alg-vae-tile-decode-sec-51\">五十一 · 选型边界：什么条件下分块解码才成立</h3>\n<p>与同族方案对照时，先分清切分发生在哪一段。阶段级流水按管线阶段切分，patch 级调度在去噪前切分并改变去噪计算图，本方案只在 VAE 解码期做空间切块，去噪路径原样不动，因此它可以叠加在任意采样器之上，代价则全部落在解码段。整图解码的峰值显存近似 <span class=\"formula\">$$\\text{Mem}_{\\text{peak}}\\approx \\text{Mem}_{\\text{tile}}+\\text{Mem}_{\\text{model}}$$</span>，分块把第一项从全图激活压到单 tile 激活；整图路线则相反，用显存换掉重叠计算与融合逻辑。判断标准很直接：若单卡能容下整图激活且解码时延已满足 SLO，分块只增加重叠区的重复卷积与写回拷贝，属于净亏损；只有当整图激活把显存推到数十 GB 量级、迫使降低批大小或跨卡切分时，分块才是唯一能在单卡完成 2048² 解码的路径。</p>\n<p>失效条件集中在两处。其一是感受野：tile 边界处解码器的有效感受野被截断，高频细节在不同 tile 间不一致，文字与细纹理处出现断裂，这类误差无法靠后处理修复，只能靠加大重叠宽度摊薄。其二是权重设计：融合式 <span class=\"formula\">$$\\hat{x}(u)=\\frac{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)\\,D_i(u)}{\\sum_{i\\in\\mathcal{N}(u)} w_i(u)},\\quad w_i(u)=\\exp\\left(-\\frac{\\|u-c_i\\|_2^2}{2\\sigma^2}\\right)$$</span> 中带宽 $\\sigma$ 过小会在重叠区留下硬切换，表现为色带或亮度跳变，收尾的色彩一致性校正只能压平全局偏移，压不住局部跳变。tile 过小则重叠占比升高，融合计算与显存拷贝开销抵消显存收益，规模上限由单 tile 感受野与权重带宽共同约束。</p>\n<p>系统代价要按请求形态折算。批大小按单 tile 显存上限设定，而非按整图；tile 间可并行，多 stream 下解码时延随 tile 数近线性下降，但重叠区的重复计算使总算力高于整图解码，吞吐收益来自显存释放后能塞进更大的批。量化侧用 FP16 解码配合 kernel 融合进一步压峰值，无需 KV 缓存，显存预算几乎全给激活与权重。</p>\n<table class=\"mini\"><thead><tr><th>相邻方案</th><th>切分位置</th><th>适用条件</th><th>主要代价</th></tr></thead><tbody><tr><td>整图解码</td><td>不切分</td><td>单卡容得下整图激活，时延已达标</td><td>显存峰值高，批大小受限</td></tr><tr><td>阶段级流水</td><td>管线阶段</td><td>多卡、阶段负载可均衡</td><td>阶段间气泡与通信</td></tr><tr><td>patch 级调度</td><td>去噪前</td><td>需改去噪计算图、追求采样期省显存</td><td>改动采样器，语义一致性风险</td></tr><tr><td>VAE 分块解码</td><td>解码期空间切块</td><td>高分辨率图/视频帧、显存受限、去噪图不可改</td><td>重叠重复计算、接缝与高频断裂</td></tr></tbody></table>\n<p>工程判断落在重叠宽度与 tile 尺寸的联合标定上：以单 tile 激活恰好填满显存余量为下界定 tile，再按解码器最深层有效感受野的两倍定重叠像素，使边界像素至少被两个 tile 以相近权重覆盖；若标定后重叠占比超过阈值仍不见显存收益，说明该分辨率应回到整图解码或改用阶段级流水，而不是继续缩小 tile。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2021 · DiT 低比特量化与数值格式</td></tr><tr><td>解决什么</td><td>高分辨率 latent 送 VAE 解码时激活显存爆炸，单张 2048² 图像解码可占数十 GB，成为端到端吞吐的显存…</td></tr><tr><td>一句话机制</td><td>把 latent 切成带重叠的 tile，逐 tile 解码后按重叠区做加权融合，配合 FP16 解码与 kernel…</td></tr><tr><td>代价与失效</td><td>重叠区融合引入额外计算与接缝风险，权重设计不当会出现色带；tile 边界处感受野截断，高频细节可能不一致</td></tr><tr><td>后继</td><td>LCM 少步一致性采样</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-vae-tile-decode · 共 8 个片段</p>\n";break;}}})();
